function(container, apiUrl, tables) {
  // ログイン試行回数を追跡
  let loginAttempts = parseInt(localStorage.getItem('loginAttempts') || '0');
  let lockoutTime = parseInt(localStorage.getItem('lockoutTime') || '0');
  const MAX_ATTEMPTS = 5;
  const LOCKOUT_DURATION = 15 * 60 * 1000; // 15分

  // DOM要素の取得
  const loginForm = container.querySelector('#login-form');
  const userIdInput = container.querySelector('#user-id');
  const passwordInput = container.querySelector('#password');
  const togglePasswordBtn = container.querySelector('#toggle-password');
  const rememberMeCheckbox = container.querySelector('#remember-me');
  const errorMessage = container.querySelector('#error-message');
  const forgotPasswordLink = container.querySelector('#forgot-password-link');

  // エラーメッセージ表示関数
  function showError(message) {
    errorMessage.textContent = message;
    errorMessage.style.display = 'block';
  }

  function hideError() {
    errorMessage.style.display = 'none';
  }

  // アカウントロック状態チェック
  function isAccountLocked() {
    const now = Date.now();
    if (lockoutTime > 0 && now < lockoutTime) {
      return true;
    }
    if (lockoutTime > 0 && now >= lockoutTime) {
      // ロック期間終了
      localStorage.removeItem('loginAttempts');
      localStorage.removeItem('lockoutTime');
      loginAttempts = 0;
      lockoutTime = 0;
    }
    return false;
  }

  // ログイン試行回数増加
  function incrementLoginAttempts() {
    loginAttempts++;
    localStorage.setItem('loginAttempts', loginAttempts.toString());

    if (loginAttempts >= MAX_ATTEMPTS) {
      lockoutTime = Date.now() + LOCKOUT_DURATION;
      localStorage.setItem('lockoutTime', lockoutTime.toString());
    }
  }

  // ログイン試行回数リセット
  function resetLoginAttempts() {
    loginAttempts = 0;
    lockoutTime = 0;
    localStorage.removeItem('loginAttempts');
    localStorage.removeItem('lockoutTime');
  }

  // バリデーション関数
  function validateForm() {
    const userId = userIdInput.value.trim();
    const password = passwordInput.value.trim();

    if (!userId && !password) {
      showError('ユーザーIDとパスワードを入力してください');
      return false;
    }
    if (!userId) {
      showError('ユーザーIDを入力してください');
      return false;
    }
    if (!password) {
      showError('パスワードを入力してください');
      return false;
    }

    // 特殊文字チェック
    const dangerousChars = /<script|javascript:|data:|vbscript:|onload|onerror|';|DROP|DELETE|INSERT|UPDATE/i;
    if (dangerousChars.test(userId) || dangerousChars.test(password)) {
      showError('不正な文字が含まれています');
      return false;
    }

    return true;
  }

  // ログイン処理
  async function handleLogin(userId, password, rememberMe) {
    try {
      // アカウントロックチェック
      if (isAccountLocked()) {
        showError('アカウントがロックされました。しばらく時間をおいてから再度お試しください。');
        return;
      }

      // ユーザーテーブル（tables[0]）からユーザー検索
      const users = tables[0].records || [];
      const user = users.find(u => u.ユーザー名 === userId && u.有効フラグ === true);

      if (!user) {
        incrementLoginAttempts();
        showError('ユーザーIDまたはパスワードが正しくありません');
        return;
      }

      // パスワード検証（実際の実装では暗号化されたパスワードと比較）
      // ここではデモ用に平文比較
      if (user.パスワードハッシュ !== password) {
        incrementLoginAttempts();
        showError('ユーザーIDまたはパスワードが正しくありません');
        return;
      }

      // ログイン成功
      resetLoginAttempts();

      // 最終ログイン日時更新
      await window.aivicApi.update(0, user.ユーザーID, {
        最終ログイン日時: new Date().toISOString()
      });

      // ログイン状態保存
      const loginData = {
        userId: user.ユーザーID,
        userName: user.ユーザー名,
        displayName: user.氏名,
        department: user.所属部署,
        role: user.権限レベル,
        loginTime: new Date().toISOString()
      };

      if (rememberMe) {
        localStorage.setItem('loginData', JSON.stringify(loginData));
      } else {
        sessionStorage.setItem('loginData', JSON.stringify(loginData));
      }

      // メイン画面（工数記録画面）に遷移
      window.showScreen("scr-1778907133295");

    } catch (error) {
      console.error('Login error:', error);
      showError('ログイン処理中にエラーが発生しました');
    }
  }

  // パスワード表示切り替え
  togglePasswordBtn.addEventListener('click', () => {
    const isPassword = passwordInput.type === 'password';
    passwordInput.type = isPassword ? 'text' : 'password';
    togglePasswordBtn.textContent = isPassword ? '🙈' : '👁️';
  });

  // フォーム送信処理
  loginForm.addEventListener('submit', async (e) => {
    e.preventDefault();
    hideError();

    if (!validateForm()) {
      return;
    }

    const userId = userIdInput.value.trim();
    const password = passwordInput.value.trim();
    const rememberMe = rememberMeCheckbox.checked;

    await handleLogin(userId, password, rememberMe);
  });

  // パスワードを忘れた場合のリンク
  forgotPasswordLink.addEventListener('click', (e) => {
    e.preventDefault();
    // パスワードリセット画面に遷移（実際の実装では適切な画面IDを指定）
    alert('パスワードリセット機能は準備中です。管理者にお問い合わせください。');
  });

  // 既存のログイン状態チェック
  const existingLogin = localStorage.getItem('loginData') || sessionStorage.getItem('loginData');
  if (existingLogin) {
    try {
      const loginData = JSON.parse(existingLogin);
      // 有効期限チェック（24時間）
      const loginTime = new Date(loginData.loginTime);
      const now = new Date();
      const hoursDiff = (now - loginTime) / (1000 * 60 * 60);

      if (hoursDiff < 24) {
        // 自動ログイン
        window.showScreen("scr-1778907133295");
        return;
      } else {
        // 期限切れ
        localStorage.removeItem('loginData');
        sessionStorage.removeItem('loginData');
      }
    } catch (error) {
      console.error('Auto login error:', error);
    }
  }

  // 初期フォーカス
  userIdInput.focus();
}

function(container, apiUrl, tables) {
  let workState = {
    isWorking: false,
    isPaused: false,
    startTime: null,
    pauseStartTime: null,
    totalPauseTime: 0,
    currentWorkId: null,
    elapsedInterval: null
  };

  // 現在時刻更新
  function updateCurrentTime() {
    const now = new Date();
    const timeStr = now.toLocaleString('ja-JP', {
      year: 'numeric',
      month: '2-digit',
      day: '2-digit',
      hour: '2-digit',
      minute: '2-digit',
      second: '2-digit'
    });
    container.querySelector('#current-datetime').textContent = timeStr;
  }

  // 経過時間更新
  function updateElapsedTime() {
    if (!workState.isWorking || !workState.startTime) return;

    const now = new Date();
    let elapsed = now - workState.startTime - workState.totalPauseTime;

    if (workState.isPaused && workState.pauseStartTime) {
      elapsed -= (now - workState.pauseStartTime);
    }

    const hours = Math.floor(elapsed / (1000 * 60 * 60));
    const minutes = Math.floor((elapsed % (1000 * 60 * 60)) / (1000 * 60));
    const seconds = Math.floor((elapsed % (1000 * 60)) / 1000);

    const timeStr = `${hours.toString().padStart(2, '0')}:${minutes.toString().padStart(2, '0')}:${seconds.toString().padStart(2, '0')}`;
    container.querySelector('#elapsed-time').textContent = timeStr;
  }

  // エラーメッセージ表示
  function showError(message) {
    const errorEl = container.querySelector('#error-message');
    errorEl.textContent = message;
    errorEl.classList.remove('hidden');
    setTimeout(() => errorEl.classList.add('hidden'), 3000);
  }

  // 作業項目選択肢を読み込み
  function loadWorkItems() {
    const workItemsTable = tables.find(t => t.tableName === '作業項目マスタ');
    if (workItemsTable) {
      const select = container.querySelector('#work-item-select');
      select.innerHTML = '<option value="">選択してください</option>';

      workItemsTable.records
        .filter(item => item.有効フラグ)
        .sort((a, b) => (a.表示順序 || 0) - (b.表示順序 || 0))
        .forEach(item => {
          const option = document.createElement('option');
          option.value = item.作業項目ID;
          option.textContent = `${item.作業項目コード} - ${item.作業項目名}`;
          select.appendChild(option);
        });
    }
  }

  // 本日の作業履歴を描画
  function renderTodayHistory(records) {
    const tbody = container.querySelector('#work-history-tbody');
    const today = new Date().toISOString().split('T')[0];

    const todayRecords = records.filter(record => {
      const recordDate = new Date(record.作業日).toISOString().split('T')[0];
      return recordDate === today;
    }).sort((a, b) => new Date(a.作業開始時刻) - new Date(b.作業開始時刻));

    tbody.innerHTML = todayRecords.map(record => {
      const startTime = new Date(record.作業開始時刻).toLocaleTimeString('ja-JP', {hour: '2-digit', minute: '2-digit'});
      const endTime = record.作業終了時刻? new Date(record.作業終了時刻).toLocaleTimeString('ja-JP', {hour: '2-digit', minute: '2-digit'}) : '-';
      const workHours = record.作業時間 ? `${Math.floor(record.作業時間 / 60)}:${(record.作業時間 % 60).toString().padStart(2, '0')}` : '-';

      return `
        <tr data-id="${record.作業記録ID}">
          <td>${startTime}</td>
          <td>${endTime}</td>
          <td>${record.プロジェクト名 || '-'}</td>
          <td>${workHours}</td>
          <td>
            <span style="padding: 2px 6px; border-radius: 4px; font-size: 11px; background: ${
              record.進捗状況 === '完了' ? 'var(--primary)' : 
              record.進捗状況 === '作業中' ? '#28a745' : 
              record.進捗状況 === '中断' ? '#ffc107' : '#6c757d'
            }; color: white;">${record.進捗状況}</span>
          </td>
          <td style="max-width: 200px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;">${record.作業内容 || record.備考 || '-'}</td>
          <td>
            <button class="action-btn secondary edit-btn" data-id="${record.作業記録ID}" style="font-size: 11px; padding: 4px 8px;">編集</button>
            <button class="action-btn secondary delete-btn" data-id="${record.作業記録ID}" style="font-size: 11px; padding: 4px 8px; margin-left: 4px;">削除</button>
          </td>
        </tr>
      `;
    }).join('');
  }

  // 初期データ読み込み
  loadWorkItems();
  renderTodayHistory(tables[1]?.records || []);

  // 定期更新開始
  updateCurrentTime();
  setInterval(updateCurrentTime, 1000);

  // 文字数カウント
  const memoTextarea = container.querySelector('#work-memo');
  const memoCount = container.querySelector('#memo-count');
  memoTextarea.addEventListener('input', () => {
    memoCount.textContent = memoTextarea.value.length;
  });

  // 作業開始ボタン
  container.querySelector('#start-work-btn').addEventListener('click', () => {
    const workItemSelect = container.querySelector('#work-item-select');
    if (!workItemSelect.value) {
      showError('作業項目を選択してください');
      return;
    }

    workState.isWorking = true;
    workState.isPaused = false;
    workState.startTime = new Date();
    workState.totalPauseTime = 0;

    // ボタン状態更新
    container.querySelector('#start-work-btn').disabled = true;
    container.querySelector('#pause-work-btn').disabled = false;
    container.querySelector('#end-work-btn').disabled = false;

    // 経過時間更新開始
    workState.elapsedInterval = setInterval(updateElapsedTime, 1000);
    updateElapsedTime();
  });

  // 中断ボタン
  container.querySelector('#pause-work-btn').addEventListener('click', () => {
    if (!workState.isWorking) {
      showError('作業が開始されていません');
      return;
    }

    container.querySelector('#pause-reason-area').classList.remove('hidden');
  });

  // 中断確定ボタン
  container.querySelector('#confirm-pause-btn').addEventListener('click', () => {
    const pauseReason = container.querySelector('#pause-reason').value.trim();
    if (!pauseReason) {
      showError('中断理由を入力してください');
      return;
    }

    workState.isPaused = true;
    workState.pauseStartTime = new Date();

    container.querySelector('#pause-reason-area').classList.add('hidden');
    container.querySelector('#pause-reason').value = '';
    container.querySelector('#pause-work-btn').textContent = '再開';
    container.querySelector('#pause-work-btn').onclick = () => {
      // 再開処理
      if (workState.pauseStartTime) {
        workState.totalPauseTime += new Date() - workState.pauseStartTime;
      }
      workState.isPaused = false;
      workState.pauseStartTime = null;
      container.querySelector('#pause-work-btn').textContent = '中断';
      container.querySelector('#pause-work-btn').onclick = null;
      container.querySelector('#pause-work-btn').addEventListener('click', arguments.callee.caller);
    };
  });

  // 中断キャンセルボタン
  container.querySelector('#cancel-pause-btn').addEventListener('click', () => {
    container.querySelector('#pause-reason-area').classList.add('hidden');
    container.querySelector('#pause-reason').value = '';
  });

  // 作業終了ボタン
  container.querySelector('#end-work-btn').addEventListener('click', () => {
    if (!workState.isWorking) {
      showError('作業が開始されていません');
      return;
    }

    // 中断中の場合は中断時間を追加
    if (workState.isPaused && workState.pauseStartTime) {
      workState.totalPauseTime += new Date() - workState.pauseStartTime;
    }

    const endTime = new Date();
    const totalWorkTime = Math.floor((endTime - workState.startTime - workState.totalPauseTime) / (1000 * 60));

    // 作業記録を保存
    const workItemSelect = container.querySelector('#work-item-select');
    const selectedOption = workItemSelect.options[workItemSelect.selectedIndex];
    const workItemName = selectedOption ? selectedOption.textContent.split(' - ')[1] : '';

    const workRecord = {
      作業員ID: 'current-user-id', // 実際の実装では現在のユーザーIDを使用
      作業日: workState.startTime.toISOString(),
      作業開始時刻: workState.startTime.toISOString(),
      作業終了時刻: endTime.toISOString(),
      作業時間: totalWorkTime,
      プロジェクト名: workItemName,
      作業場所: '現場A', // 実際の実装では選択可能にする
      作業種別: '一般作業',
      作業内容: container.querySelector('#work-memo').value,
      進捗状況: '完了',
      備考: '',
      承認状態: '未承認',
      作成者ID: 'current-user-id'
    };

    window.aivicApi.save(1, workRecord).then(saved => {
      if (saved) {
        // 状態リセット
        workState.isWorking = false;
        workState.isPaused = false;
        workState.startTime = null;
        workState.pauseStartTime = null;
        workState.totalPauseTime = 0;

        if (workState.elapsedInterval) {
          clearInterval(workState.elapsedInterval);
          workState.elapsedInterval = null;
        }

        // UI リセット
        container.querySelector('#start-work-btn').disabled = false;
        container.querySelector('#pause-work-btn').disabled = true;
        container.querySelector('#end-work-btn').disabled = true;
        container.querySelector('#elapsed-time').textContent = '00:00:00';
        container.querySelector('#work-memo').value = '';
        container.querySelector('#memo-count').textContent = '0';
        container.querySelector('#work-item-select').value = '';

        // 履歴更新
        window.aivicApi.list(1).then(records => {
          if (records) renderTodayHistory(records);
        });
      }
    });
  });

  // 保存ボタン
  container.querySelector('#save-work-btn').addEventListener('click', () => {
    const workItemSelect = container.querySelector('#work-item-select');
    const memo = container.querySelector('#work-memo').value.trim();

    if (!workItemSelect.value && !memo) {
      showError('作業項目または作業メモを入力してください');
      return;
    }

    // 手動記録として保存
    const selectedOption = workItemSelect.options[workItemSelect.selectedIndex];
    const workItemName = selectedOption ? selectedOption.textContent.split(' - ')[1] : '';

    const workRecord = {
      作業員ID: 'current-user-id',
      作業日: new Date().toISOString(),
      作業開始時刻: new Date().toISOString(),
      作業終了時刻: null,
      作業時間: null,
      プロジェクト名: workItemName,
      作業場所: '現場A',
      作業種別: '一般作業',
      作業内容: memo,
      進捗状況: '記録のみ',
      備考: '手動記録',
      承認状態: '未承認',
      作成者ID: 'current-user-id'
    };

    window.aivicApi.save(1, workRecord).then(saved => {
      if (saved) {
        container.querySelector('#work-memo').value = '';
        container.querySelector('#memo-count').textContent = '0';
        container.querySelector('#work-item-select').value = '';

        window.aivicApi.list(1).then(records => {
          if (records) renderTodayHistory(records);
        });
      }
    });
  });

  // キャンセルボタン
  container.querySelector('#cancel-work-btn').addEventListener('click', () => {
    if (workState.isWorking) {
      if (!confirm('作業中です。キャンセルしますか？未保存のデータは失われます。')) {
        return;
      }

      // 作業状態リセット
      workState.isWorking = false;
      workState.isPaused = false;
      workState.startTime = null;
      workState.pauseStartTime = null;
      workState.totalPauseTime = 0;

      if (workState.elapsedInterval) {
        clearInterval(workState.elapsedInterval);
        workState.elapsedInterval = null;
      }

      // ボタン状態リセット
      container.querySelector('#start-work-btn').disabled = false;
      container.querySelector('#pause-work-btn').disabled = true;
      container.querySelector('#end-work-btn').disabled = true;
      container.querySelector('#elapsed-time').textContent = '00:00:00';
    }

    // フォームクリア
    container.querySelector('#work-memo').value = '';
    container.querySelector('#memo-count').textContent = '0';
    container.querySelector('#work-item-select').value = '';
    container.querySelector('#pause-reason-area').classList.add('hidden');
  });

  // 行レベル操作（削除・編集）
  container.addEventListener('click', async (e) => {
    const deleteBtn = e.target.closest('.delete-btn');
    const editBtn = e.target.closest('.edit-btn');

    if (deleteBtn) {
      if (!confirm('この作業記録を削除しますか？')) return;

      const success = await window.aivicApi.delete(1, deleteBtn.dataset.id);
      if (success) {
        const records = await window.aivicApi.list(1);
        if (records) renderTodayHistory(records);
      }
    }

    if (editBtn) {
      // 編集機能は簡略化（実際の実装では編集フォームを表示）
      alert('編集機能は作業履歴一覧画面で利用できます');
    }
  });
}

function(container, apiUrl, tables) {
  const tbody = container.querySelector('#work-history-tbody');
  const resultCount = container.querySelector('#result-count');
  const noResults = container.querySelector('#no-results');
  const errorMessage = container.querySelector('#error-message');
  const workItemFilter = container.querySelector('#filter-work-item');

  let allWorkRecords = [];
  let allWorkItems = [];
  let allBreakRecords = [];

  // 中断回数を計算する関数
  function getBreakCount(workRecordId) {
    return allBreakRecords.filter(br => br.作業記録ID === workRecordId).length;
  }

  // 作業時間をフォーマットする関数
  function formatWorkTime(minutes) {
    if (!minutes) return '-';
    const hours = Math.floor(minutes / 60);
    const mins = minutes % 60;
    return hours > 0 ? `${hours}時間${mins}分` : `${mins}分`;
  }

  // 日時をフォーマットする関数
  function formatDateTime(dateTimeStr) {
    if (!dateTimeStr) return '-';
    const date = new Date(dateTimeStr);
    return date.toLocaleString('ja-JP', {
      year: 'numeric',
      month: '2-digit',
      day: '2-digit',
      hour: '2-digit',
      minute: '2-digit'
    });
  }

  // 時刻のみをフォーマットする関数
  function formatTime(dateTimeStr) {
    if (!dateTimeStr) return '-';
    const date = new Date(dateTimeStr);
    return date.toLocaleTimeString('ja-JP', {
      hour: '2-digit',
      minute: '2-digit'
    });
  }

  // エラーメッセージを表示する関数
  function showError(message) {
    errorMessage.textContent = message;
    errorMessage.style.display = 'block';
    setTimeout(() => {
      errorMessage.style.display = 'none';
    }, 5000);
  }

  // テーブル再描画関数
  function renderRows(rows) {
    if (!rows || rows.length === 0) {
      tbody.innerHTML = '';
      resultCount.textContent = '0';
      noResults.style.display = 'block';
      container.querySelector('.table-wrap').style.display = 'none';
      return;
    }

    noResults.style.display = 'none';
    container.querySelector('.table-wrap').style.display = 'block';

    tbody.innerHTML = rows.map(r => {
      const breakCount = getBreakCount(r.作業記録ID);
      const statusBadge = r.進捗状況 === '完了' ? 
        '<span style="background: rgba(34, 197, 94, 0.2); color: #22c55e; padding: 2px 6px; border-radius: 4px; font-size: 11px;">完了</span>' :
        r.進捗状況 === '進行中' ? 
        '<span style="background: rgba(59, 130, 246, 0.2); color: #3b82f6; padding: 2px 6px; border-radius: 4px; font-size: 11px;">進行中</span>' :
        '<span style="background: rgba(239, 68, 68, 0.2); color: #ef4444; padding: 2px 6px; border-radius: 4px; font-size: 11px;">中断</span>';

      return `
        <tr data-id="${r.作業記録ID}" style="border-bottom: 1px solid rgba(255,255,255,0.02);">
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${formatDateTime(r.作業日)}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${r.作業種別 || '-'}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${formatTime(r.作業開始時刻)}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${formatTime(r.作業終了時刻)}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${formatWorkTime(r.作業時間)}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text); text-align: center;">${breakCount}</td>
          <td style="padding: 6px 10px; font-size: 13px;">${statusBadge}</td>
          <td style="padding: 6px 10px;">
            <button class="action-btn secondary detail-btn" data-id="${r.作業記録ID}" style="background: transparent; color: var(--text); border: 1px solid rgba(255,255,255,0.18); padding: 4px 8px; border-radius: 4px; font-size: 11px; cursor: pointer;">詳細確認</button>
          </td>
        </tr>
      `;
    }).join('');

    resultCount.textContent = rows.length.toString();
  }

  // 作業項目フィルターを初期化
  function initWorkItemFilter() {
    if (allWorkItems.length > 0) {
      workItemFilter.innerHTML = '<option value="">すべて</option>' + 
        allWorkItems.map(item => `<option value="${item.作業項目名}">${item.作業項目名}</option>`).join('');
    }
  }

  // バリデーション関数
  function validateDateRange(startDate, endDate) {
    if (startDate && endDate) {
      const start = new Date(startDate);
      const end = new Date(endDate);
      const today = new Date();
      today.setHours(23, 59, 59, 999);

      if (start > today || end > today) {
        showError('未来の日付は選択できません');
        return false;
      }

      if (start > end) {
        showError('開始日は終了日より前の日付を入力してください');
        return false;
      }

      const diffTime = Math.abs(end - start);
      const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
      if (diffDays > 365) {
        showError('1年以上の期間は選択できません');
        return false;
      }
    }
    return true;
  }

  // フィルター実行関数
  function executeFilter() {
    const startDate = container.querySelector('#filter-start-date').value;
    const endDate = container.querySelector('#filter-end-date').value;
    const workItem = container.querySelector('#filter-work-item').value;
    const status = container.querySelector('#filter-status').value;

    if (!validateDateRange(startDate, endDate)) {
      return;
    }

    let filteredRows = [...allWorkRecords];

    // 日付範囲フィルター
    if (startDate || endDate) {
      filteredRows = filteredRows.filter(r => {
        const workDate = new Date(r.作業日);
        const start = startDate ? new Date(startDate) : null;
        const end = endDate ? new Date(endDate + 'T23:59:59') : null;

        if (start && workDate < start) return false;
        if (end && workDate > end) return false;
        return true;
      });
    }

    // 作業項目フィルター
    if (workItem) {
      filteredRows = filteredRows.filter(r => r.作業種別 === workItem);
    }

    // 状況フィルター
    if (status) {
      filteredRows = filteredRows.filter(r => r.進捗状況 === status);
    }

    // 作業日時の降順でソート
    filteredRows.sort((a, b) => new Date(b.作業日) - new Date(a.作業日));

    renderRows(filteredRows);
  }

  // CSVエクスポート関数
  function exportCSV() {
    const startDate = container.querySelector('#filter-start-date').value;
    const endDate = container.querySelector('#filter-end-date').value;
    const workItem = container.querySelector('#filter-work-item').value;
    const status = container.querySelector('#filter-status').value;

    let exportRows = [...allWorkRecords];

    // 現在のフィルター条件を適用
    if (startDate || endDate) {
      exportRows = exportRows.filter(r => {
        const workDate = new Date(r.作業日);
        const start = startDate ? new Date(startDate) : null;
        const end = endDate ? new Date(endDate + 'T23:59:59') : null;

        if (start && workDate < start) return false;
        if (end && workDate > end) return false;
        return true;
      });
    }

    if (workItem) {
      exportRows = exportRows.filter(r => r.作業種別 === workItem);
    }

    if (status) {
      exportRows = exportRows.filter(r => r.進捗状況 === status);
    }

    const headers = ['作業日時', '作業項目名', '開始時刻', '終了時刻', '作業時間', '中断回数', '状況', 'プロジェクト名', '作業場所', '作業内容'];
    const csvContent = '\uFEFF' + headers.join(',') + '\n' + 
      exportRows.map(r => {
        const breakCount = getBreakCount(r.作業記録ID);
        return [
          formatDateTime(r.作業日),
          r.作業種別 || '',
          formatTime(r.作業開始時刻),
          formatTime(r.作業終了時刻),
          formatWorkTime(r.作業時間),
          breakCount,
          r.進捗状況 || '',
          r.プロジェクト名 || '',
          r.作業場所 || '',
          (r.作業内容 || '').replace(/,/g, '，').replace(/\n/g, ' ')
        ].map(field => `"${field}"`).join(',');
      }).join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `作業履歴_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  }

  // 初期データ読み込み
  Promise.all([
    window.aivicApi.list(1), // 作業記録
    window.aivicApi.list(3), // 作業項目マスタ
    window.aivicApi.list(2)  // 中断記録
  ]).then(([workRecords, workItems, breakRecords]) => {
    allWorkRecords = workRecords || tables[1]?.records || [];
    allWorkItems = workItems || tables[3]?.records || [];
    allBreakRecords = breakRecords || tables[2]?.records || [];

    initWorkItemFilter();
    executeFilter();
  }).catch(() => {
    allWorkRecords = tables[1]?.records || [];
    allWorkItems = tables[3]?.records || [];
    allBreakRecords = tables[2]?.records || [];

    initWorkItemFilter();
    executeFilter();
  });

  // 検索ボタンイベント
  container.querySelector('#btn-search').addEventListener('click', executeFilter);

  // リセットボタンイベント
  container.querySelector('#btn-reset').addEventListener('click', () => {
    container.querySelector('#filter-start-date').value = '';
    container.querySelector('#filter-end-date').value = '';
    container.querySelector('#filter-work-item').value = '';
    container.querySelector('#filter-status').value = '';
    executeFilter();
  });

  // CSVエクスポートボタンイベント
  container.querySelector('#btn-csv-export').addEventListener('click', exportCSV);

  // データ抽出ボタンイベント
  container.querySelector('#btn-data-extract').addEventListener('click', () => {
    window.showScreen('scr-1778907353387');
  });

  // 戻るボタンイベント
  container.querySelector('#btn-back').addEventListener('click', () => {
    window.showScreen('scr-1778907133295');
  });

  // 行レベル操作のイベントデリゲーション
  container.addEventListener('click', (e) => {
    const detailBtn = e.target.closest('.detail-btn');
    if (detailBtn) {
      window.showScreen('scr-1778907367889');
    }
  });
}

function(container, apiUrl, tables) {
  let currentUser = { id: 'user-001', name: '田中太郎' };
  let activeWorks = [];
  let pausedWorks = [];
  let workItems = [];
  let elapsedTimers = new Map();

  // 現在日時更新
  function updateCurrentTime() {
    const now = new Date();
    const formatted = `${now.getFullYear()}/${String(now.getMonth() + 1).padStart(2, '0')}/${String(now.getDate()).padStart(2, '0')} ${String(now.getHours()).padStart(2, '0')}:${String(now.getMinutes()).padStart(2, '0')}`;
    container.querySelector('#current-datetime').textContent = formatted;
  }

  // 経過時間計算
  function calculateElapsedTime(startTime) {
    const start = new Date(startTime);
    const now = new Date();
    const diffMs = now - start;
    const hours = Math.floor(diffMs / (1000 * 60 * 60));
    const minutes = Math.floor((diffMs % (1000 * 60 * 60)) / (1000 * 60));
    return `${hours}時間${minutes}分`;
  }

  // 進行中作業の再描画
  function renderActiveWorks() {
    const tbody = container.querySelector('#active-works-tbody');
    const noActiveDiv = container.querySelector('#no-active-works');
    const tableDiv = container.querySelector('#active-works-table');

    if (activeWorks.length === 0) {
      noActiveDiv.classList.remove('hidden');
      tableDiv.classList.add('hidden');
      return;
    }

    noActiveDiv.classList.add('hidden');
    tableDiv.classList.remove('hidden');

    tbody.innerHTML = activeWorks.map(work => {
      const startTime = new Date(work.作業開始時刻).toLocaleString('ja-JP', { 
        month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit' 
      });
      const elapsed = calculateElapsedTime(work.作業開始時刻);

      return `
        <tr data-id="${work.作業記録ID}">
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${work.作業内容 || ''}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${startTime}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);" class="elapsed-time">${elapsed}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${work.作業場所 || ''}</td>
          <td style="padding: 6px 10px;">
            <button class="action-btn" data-testid="work-input-button" onclick="window.showScreen('scr-1778907296658')" style="padding: 4px 8px; font-size: 12px;">工数入力</button>
          </td>
        </tr>
      `;
    }).join('');

    // 経過時間の更新タイマー
    activeWorks.forEach(work => {
      if (!elapsedTimers.has(work.作業記録ID)) {
        const timer = setInterval(() => {
          const row = tbody.querySelector(`tr[data-id="${work.作業記録ID}"]`);
          if (row) {
            const elapsedCell = row.querySelector('.elapsed-time');
            if (elapsedCell) {
              elapsedCell.textContent = calculateElapsedTime(work.作業開始時刻);
            }
          }
        }, 60000); // 1分ごと更新
        elapsedTimers.set(work.作業記録ID, timer);
      }
    });
  }

  // 中断中作業の再描画
  function renderPausedWorks() {
    const tbody = container.querySelector('#paused-works-tbody');
    const noPausedDiv = container.querySelector('#no-paused-works');
    const tableDiv = container.querySelector('#paused-works-table');

    if (pausedWorks.length === 0) {
      noPausedDiv.classList.remove('hidden');
      tableDiv.classList.add('hidden');
      return;
    }

    noPausedDiv.classList.add('hidden');
    tableDiv.classList.remove('hidden');

    tbody.innerHTML = pausedWorks.map(work => {
      const pauseTime = new Date(work.中断開始日時).toLocaleString('ja-JP', { 
        month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit' 
      });

      return `
        <tr data-id="${work.中断記録ID}">
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${work.作業内容 || ''}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${pauseTime}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${work.中断理由詳細 || work.中断理由区分 || ''}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${work.作業場所 || ''}</td>
          <td style="padding: 6px 10px;">
            <button class="action-btn resume-btn" data-id="${work.中断記録ID}" style="padding: 4px 8px; font-size: 12px;">再開</button>
          </td>
        </tr>
      `;
    }).join('');
  }

  // 作業項目選択肢の設定
  function populateWorkItems() {
    const select = container.querySelector('#work-item-select');
    select.innerHTML = '<option value="">作業項目を選択してください</option>';

    workItems.forEach(item => {
      const option = document.createElement('option');
      option.value = item.作業項目ID;
      option.textContent = `${item.作業項目コード} - ${item.作業項目名}`;
      select.appendChild(option);
    });
  }

  // エラーメッセージ表示
  function showError(message) {
    const errorDiv = container.querySelector('#error-message');
    errorDiv.textContent = message;
    errorDiv.classList.remove('hidden');
    setTimeout(() => {
      errorDiv.classList.add('hidden');
    }, 5000);
  }

  // 確認ダイアログ表示
  function showConfirmDialog(title, message, onConfirm) {
    const dialog = container.querySelector('#confirm-dialog');
    container.querySelector('#dialog-title').textContent = title;
    container.querySelector('#dialog-message').textContent = message;
    dialog.classList.remove('hidden');

    const confirmBtn = container.querySelector('#dialog-confirm');
    const cancelBtn = container.querySelector('#dialog-cancel');

    const handleConfirm = () => {
      dialog.classList.add('hidden');
      confirmBtn.removeEventListener('click', handleConfirm);
      cancelBtn.removeEventListener('click', handleCancel);
      onConfirm();
    };

    const handleCancel = () => {
      dialog.classList.add('hidden');
      confirmBtn.removeEventListener('click', handleConfirm);
      cancelBtn.removeEventListener('click', handleCancel);
    };

    confirmBtn.addEventListener('click', handleConfirm);
    cancelBtn.addEventListener('click', handleCancel);
  }

  // データ読み込み
  async function loadData() {
    try {
      // 作業項目マスタ読み込み
      const workItemsData = await window.aivicApi.list(3);
      if (workItemsData) {
        workItems = workItemsData.filter(item => item.有効フラグ);
        populateWorkItems();
      }

      // 進行中作業読み込み
      const workRecords = await window.aivicApi.list(1);
      if (workRecords) {
        activeWorks = workRecords.filter(record => 
          record.作業員ID === currentUser.id && 
          record.進捗状況 === '作業中' && 
          !record.作業終了時刻
        );
        renderActiveWorks();
      }

      // 中断中作業読み込み
      const pauseRecords = await window.aivicApi.list(2);
      if (pauseRecords) {
        pausedWorks = pauseRecords.filter(record => 
          record.記録者ID === currentUser.id && 
          record.対応状況 === '対応中' && 
          !record.中断終了日時
        );
        renderPausedWorks();
      }
    } catch (error) {
      console.error('データ読み込みエラー:', error);
    }
  }

  // 初期化
  updateCurrentTime();
  setInterval(updateCurrentTime, 60000);
  container.querySelector('#current-user-name').textContent = currentUser.name;
  loadData();

  // 備考文字数カウンター
  const notesInput = container.querySelector('#work-notes-input');
  const notesCounter = container.querySelector('#notes-counter');
  notesInput.addEventListener('input', () => {
    notesCounter.textContent = notesInput.value.length;
  });

  // クリアボタン
  container.querySelector('#btn-clear').addEventListener('click', () => {
    container.querySelector('#work-item-select').value = '';
    container.querySelector('#work-location-input').value = '';
    container.querySelector('#work-notes-input').value = '';
    notesCounter.textContent = '0';
    container.querySelector('#error-message').classList.add('hidden');
  });

  // 記録開始ボタン
  container.querySelector('#btn-start-work').addEventListener('click', async () => {
    const workItemId = container.querySelector('#work-item-select').value;
    const workLocation = container.querySelector('#work-location-input').value.trim();
    const workNotes = container.querySelector('#work-notes-input').value.trim();

    // バリデーション
    if (!workItemId) {
      showError('作業項目を選択してください。');
      return;
    }

    // 既に進行中の作業があるかチェック
    if (activeWorks.length > 0) {
      showError('既に実行中の作業があります。同時に複数の作業を開始することはできません。');
      return;
    }

    // 作業場所の文字数チェック
    if (workLocation.length > 100) {
      showError('作業場所は100文字以内で入力してください。');
      return;
    }

    // 備考の文字数チェック
    if (workNotes.length > 500) {
      showError('備考は500文字以内で入力してください。');
      return;
    }

    // 不正文字チェック
    if (/<script|javascript:|on\w+=/i.test(workLocation)) {
      showError('作業場所に不正な文字が含まれています。');
      return;
    }

    try {
      const selectedWorkItem = workItems.find(item => item.作業項目ID === workItemId);
      const now = new Date().toISOString();

      const workRecord = {
        作業員ID: currentUser.id,
        作業日: now,
        作業開始時刻: now,
        プロジェクト名: selectedWorkItem?.作業項目名|| '',
        作業場所: workLocation,
        作業種別: selectedWorkItem?.カテゴリ || '',
        作業内容: selectedWorkItem?.作業項目名|| '',
        進捗状況: '作業中',
        備考: workNotes,
        承認状態: '未承認',
        作成者ID: currentUser.id
      };

      const saved = await window.aivicApi.save(1, workRecord);
      if (saved) {
        // フォームクリア
        container.querySelector('#work-item-select').value = '';
        container.querySelector('#work-location-input').value = '';
        container.querySelector('#work-notes-input').value = '';
        notesCounter.textContent = '0';

        // データ再読み込み
        await loadData();

        // 工数入力画面に遷移
        window.showScreen('scr-1778907296658');
      }
    } catch (error) {
      showError('作業記録の開始に失敗しました。');
      console.error('作業開始エラー:', error);
    }
  });

  // 中断作業再開
  container.addEventListener('click', async (e) => {
    const resumeBtn = e.target.closest('.resume-btn');
    if (resumeBtn) {
      const pauseRecordId = resumeBtn.dataset.id;
      const pauseRecord = pausedWorks.find(p => p.中断記録ID === pauseRecordId);

      if (!pauseRecord) {
        showError('指定された作業が見つかりません。');
        return;
      }

      showConfirmDialog(
        '作業再開確認',
        '中断中の作業を再開しますか？',
        async () => {
          try {
            // 中断記録を終了
            const updatedPause = await window.aivicApi.update(2, pauseRecordId, {
              中断終了日時: new Date().toISOString(),
              対応状況: '解決済み'
            });

            if (updatedPause) {
              // 作業記録を作業中に戻す
              const workRecord = await window.aivicApi.list(1);
              const targetWork = workRecord?.find(w => w.作業記録ID === pauseRecord.作業記録ID);

              if (targetWork) {
                await window.aivicApi.update(1, targetWork.作業記録ID, {
                  進捗状況: '作業中'
                });
              }

              await loadData();
            }
          } catch (error) {
            showError('作業の再開に失敗しました。');
            console.error('作業再開エラー:', error);
          }
        }
      );
    }
  });

  // 設定ボタン
  container.querySelector('#btn-settings').addEventListener('click', () => {
    // 設定画面への遷移（実装予定）
    alert('設定画面は準備中です。');
  });

  // ログアウトボタン
  container.querySelector('#btn-logout').addEventListener('click', () => {
    showConfirmDialog(
      'ログアウト確認',
      'ログアウトしますか？',
      () => {
        // セッションクリア
        sessionStorage.clear();
        localStorage.removeItem('currentUser');

        // ログイン画面へ遷移
        window.location.href = './login.html';
      }
    );
  });

  // クリーンアップ
  return () => {
    elapsedTimers.forEach(timer => clearInterval(timer));
    elapsedTimers.clear();
  };
}

function(container, apiUrl, tables) {
  // 現在の作業記録データ（実際の実装では前画面から受け取る）
  let currentWorkRecord = {
    id: 'current-work-001',
    workItemName: 'システム保守作業',
    startTime: '09:00',
    endTime: '17:30',
    totalTime: '8:30',
    breakTime: '1:00',
    actualWorkTime: '7:30'
  };

  // DOM要素の取得
  const workMemoInput = container.querySelector('#work-memo');
  const completionStatusSelect = container.querySelector('#completion-status');
  const hasIssueCheckbox = container.querySelector('#has-issue');
  const issueContentSection = container.querySelector('#issue-content-section');
  const issueContentInput = container.querySelector('#issue-content');
  const errorMessage = container.querySelector('#error-message');
  const memoCountSpan = container.querySelector('#memo-count');
  const issueCountSpan = container.querySelector('#issue-count');

  // 初期表示データの設定
  container.querySelector('#work-item-name').textContent = currentWorkRecord.workItemName;
  container.querySelector('#start-time').textContent = currentWorkRecord.startTime;
  container.querySelector('#end-time').textContent = currentWorkRecord.endTime;
  container.querySelector('#total-time').textContent = currentWorkRecord.totalTime;
  container.querySelector('#break-time').textContent = currentWorkRecord.breakTime;
  container.querySelector('#actual-work-time').textContent = currentWorkRecord.actualWorkTime;

  // エラーメッセージ表示関数
  function showError(message) {
    errorMessage.textContent = message;
    errorMessage.style.display = 'block';
    errorMessage.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
  }

  function hideError() {
    errorMessage.style.display = 'none';
  }

  // 文字数カウント更新
  function updateMemoCount() {
    const count = workMemoInput.value.length;
    memoCountSpan.textContent = count;
    if (count > 1000) {
      memoCountSpan.style.color = '#dc3545';
    } else {
      memoCountSpan.style.color = 'var(--text-muted)';
    }
  }

  function updateIssueCount() {
    const count = issueContentInput.value.length;
    issueCountSpan.textContent = count;
    if (count > 500) {
      issueCountSpan.style.color = '#dc3545';
    } else {
      issueCountSpan.style.color = 'var(--text-muted)';
    }
  }

  // バリデーション関数
  function validateForm() {
    hideError();

    // 完了状況の必須チェック
    if (!completionStatusSelect.value) {
      showError('完了状況を選択してください。');
      completionStatusSelect.focus();
      return false;
    }

    // 作業メモの文字数チェック
    if (workMemoInput.value.length > 1000) {
      showError('作業メモは1000文字以内で入力してください。');
      workMemoInput.focus();
      return false;
    }

    // 異常報告チェック時の異常内容必須チェック
    if (hasIssueCheckbox.checked) {
      if (!issueContentInput.value.trim()) {
        showError('異常内容を入力してください。');
        issueContentInput.focus();
        return false;
      }
      if (issueContentInput.value.length > 500) {
        showError('異常内容は500文字以内で入力してください。');
        issueContentInput.focus();
        return false;
      }
    }

    return true;
  }

  // 異常報告チェックボックスの変更イベント
  hasIssueCheckbox.addEventListener('change', function() {
    if (this.checked) {
      issueContentSection.style.display = 'block';
    } else {
      issueContentSection.style.display = 'none';
      issueContentInput.value = '';
      updateIssueCount();
    }
    hideError();
  });

  // 文字数カウントイベント
  workMemoInput.addEventListener('input', updateMemoCount);
  issueContentInput.addEventListener('input', updateIssueCount);

  // 初期文字数カウント
  updateMemoCount();
  updateIssueCount();

  // キャンセルボタン
  container.querySelector('#btn-cancel').addEventListener('click', function() {
    // 前画面に戻る（実際の実装では適切な画面IDを指定）
    history.back();
  });

  // 記録確定ボタン
  container.querySelector('#btn-confirm').addEventListener('click', async function() {
    if (!validateForm()) {
      return;
    }

    try {
      // 作業記録の更新データを準備
      const updateData = {
        作業終了時刻: new Date().toISOString(),
        作業時間: calculateWorkMinutes(currentWorkRecord.actualWorkTime),
        進捗状況: completionStatusSelect.value,
        備考: workMemoInput.value || null,
        承認状態: '未承認'
      };

      // 作業記録を更新
      const updated = await window.aivicApi.update(1, currentWorkRecord.id, updateData);
      if (!updated) {
        showError('記録の保存に失敗しました。');
        return;
      }

      // 異常報告がある場合は異常値検出ログに保存
      if (hasIssueCheckbox.checked && issueContentInput.value.trim()) {
        const anomalyData = {
          検出対象テーブル: '作業記録',
          検出対象レコードID: currentWorkRecord.id,
          ユーザーID: 'current-user-id', // 実際の実装では現在のユーザーIDを取得
          異常値種別: '作業員報告',
          検出項目: '異常・問題報告',
          検出値: issueContentInput.value,
          閾値: '手動報告',
          重要度: '中',
          確認状況: '未確認',
          通知送信フラグ: true,
          検出日時: new Date().toISOString(),
          作成日時: new Date().toISOString(),
          更新日時: new Date().toISOString()
        };

        await window.aivicApi.save(4, anomalyData);
      }

      alert('工数記録を確定しました。');
      // 記録一覧画面などに遷移（実際の実装では適切な画面IDを指定）
      history.back();

    } catch (error) {
      console.error('記録確定エラー:', error);
      showError('記録の確定中にエラーが発生しました。');
    }
  });

  // 記録確認ボタン
  container.querySelector('#btn-check-record').addEventListener('click', function() {
    window.showScreen("scr-1778907226171");
  });

  // 作業時間を分単位に変換する関数
  function calculateWorkMinutes(timeString) {
    const [hours, minutes] = timeString.split(':').map(Number);
    return hours * 60 + minutes;
  }

  // ボタンのホバーエフェクト
  const buttons = container.querySelectorAll('button');
  buttons.forEach(button => {
    button.addEventListener('mouseenter', function() {
      if (this.style.background === 'var(--primary)') {
        this.style.background = 'var(--primary-hover)';
      } else if (this.style.background === 'transparent') {
        this.style.background = 'rgba(255,255,255,0.05)';
      }
    });

    button.addEventListener('mouseleave', function() {
      if (this.id === 'btn-confirm') {
        this.style.background = 'var(--primary)';
      } else {
        this.style.background = 'transparent';
      }
    });
  });

  // フォーカス時のスタイル
  const inputs = container.querySelectorAll('input, select, textarea');
  inputs.forEach(input => {
    input.addEventListener('focus', function() {
      this.style.outline = 'none';
      this.style.borderColor = 'var(--primary)';
      this.style.boxShadow = '0 0 0 2px rgba(255,255,255,0.08)';
    });

    input.addEventListener('blur', function() {
      this.style.borderColor = 'rgba(255,255,255,0.18)';
      this.style.boxShadow = 'none';
    });
  });
}

function(container, apiUrl, tables) {
  let autoSaveInterval = null;
  let currentSaveInterval = 30; // デフォルト30秒
  let pendingData = [];
  let isOnline = navigator.onLine;
  let lastSaveTime = null;

  // ローカルストレージキー
  const LOCAL_STORAGE_KEY = 'workRecordAutoSave';
  const SETTINGS_KEY = 'autoSaveSettings';

  // 設定の読み込み
  function loadSettings() {
    const saved = localStorage.getItem(SETTINGS_KEY);
    if (saved) {
      const settings = JSON.parse(saved);
      currentSaveInterval = settings.interval || 30;
      container.querySelector('#save-interval').value = currentSaveInterval;
    }
  }

  // 設定の保存
  function saveSettings() {
    const settings = {
      interval: currentSaveInterval,
      lastUpdate: new Date().toISOString()
    };
    localStorage.setItem(SETTINGS_KEY, JSON.stringify(settings));
  }

  // ローカルデータの読み込み
  function loadLocalData() {
    const saved = localStorage.getItem(LOCAL_STORAGE_KEY);
    if (saved) {
      try {
        pendingData = JSON.parse(saved);
      } catch (e) {
        pendingData = [];
      }
    }
    updatePendingCount();
    renderLocalData();
  }

  // ローカルデータの保存
  function saveLocalData() {
    localStorage.setItem(LOCAL_STORAGE_KEY, JSON.stringify(pendingData));
  }

  // ローカルデータテーブルの描画
  function renderLocalData() {
    const tbody = container.querySelector('#local-data-tbody');
    if (!pendingData.length) {
      tbody.innerHTML = '<tr><td colspan="4" style="padding: 20px; text-align: center; color: var(--text-muted); font-size: 12px;">ローカル保存データはありません</td></tr>';
      return;
    }

    tbody.innerHTML = pendingData.map(item => `
      <tr data-id="${item.id}">
        <td style="padding: 6px 10px; font-size: 12px; color: var(--text);">${new Date(item.作業日).toLocaleString()}</td>
        <td style="padding: 6px 10px; font-size: 12px; color: var(--text);">${(item.作業内容 || '').substring(0, 30)}${(item.作業内容 || '').length > 30 ? '...' : ''}</td>
        <td style="padding: 6px 10px; font-size: 12px;">
          <span style="background: ${item.synced ? '#22c55e' : '#f59e0b'}; color: #fff; padding: 2px 6px; border-radius: 4px; font-size: 11px;">
            ${item.synced ? '同期済み' : '未同期'}
          </span>
        </td>
        <td style="padding: 6px 10px;">
          ${!item.synced ? `<button class="delete-local-btn action-btn secondary" data-id="${item.id}" style="background: transparent; color: var(--text); border: 1px solid rgba(255,255,255,0.18); padding: 2px 8px; border-radius: 4px; font-size: 11px; cursor: pointer;">削除</button>` : ''}
        </td>
      </tr>
    `).join('');
  }

  // 同期待ち件数の更新
  function updatePendingCount() {
    const count = pendingData.filter(item => !item.synced).length;
    container.querySelector('#pending-count').textContent = count;

    // 上限チェック（100件）
    if (count >= 100) {
      showError('同期待ちデータが上限（100件）に達しました。手動同期を実行してください。');
    }
  }

  // 最終保存時刻の更新
  function updateLastSaveTime() {
    lastSaveTime = new Date();
    container.querySelector('#last-save-time').textContent = lastSaveTime.toLocaleString();
  }

  // ネットワーク状態の更新
  function updateNetworkStatus() {
    const statusEl = container.querySelector('#network-status');
    const textEl = container.querySelector('#network-text');

    if (isOnline) {
      statusEl.style.background = '#22c55e';
      textEl.textContent = 'オンライン';
    } else {
      statusEl.style.background = '#ef4444';
      textEl.textContent = 'オフライン';
    }
  }

  // 自動保存ステータスの更新
  function updateAutoSaveStatus(status, text) {
    const statusEl = container.querySelector('#auto-save-status');
    const textEl = container.querySelector('#auto-save-text');

    statusEl.style.background = status === 'success' ? '#22c55e' : 
                               status === 'error' ? '#ef4444' : '#f59e0b';
    textEl.textContent = text;
  }

  // エラー表示
  function showError(message) {
    const errorEl = container.querySelector('#error-notification');
    const messageEl = container.querySelector('#error-message');

    messageEl.textContent = message;
    errorEl.classList.remove('hidden');

    // 10秒後に自動で非表示
    setTimeout(() => {
      errorEl.classList.add('hidden');
    }, 10000);
  }

  // エラー非表示
  function hideError() {
    container.querySelector('#error-notification').classList.add('hidden');
  }

  // 自動保存の実行
  async function performAutoSave() {
    try {
      updateAutoSaveStatus('working', '保存中...');

      // 未同期データがある場合は同期を試行
      const unsyncedData = pendingData.filter(item => !item.synced);

      if (unsyncedData.length > 0 && isOnline) {
        await syncPendingData();
      }

      updateAutoSaveStatus('success', '正常動作中');
      updateLastSaveTime();

    } catch (error) {
      console.error('Auto save error:', error);
      updateAutoSaveStatus('error', '保存エラー');
      showError('自動保存に失敗しました: ' + error.message);
    }
  }

  // 未同期データの同期
  async function syncPendingData() {
    const unsyncedData = pendingData.filter(item => !item.synced);

    for (const item of unsyncedData) {
      try {
        // 作業記録テーブル（tableIndex: 1）に保存
        const saved = await window.aivicApi.save(1, {
          作業員ID: item.作業員ID,
          作業日: item.作業日,
          作業開始時刻: item.作業開始時刻,
          作業終了時刻: item.作業終了時刻,
          作業時間: item.作業時間,
          プロジェクト名: item.プロジェクト名,
          作業場所: item.作業場所,
          作業種別: item.作業種別,
          作業内容: item.作業内容,
          進捗状況: item.進捗状況,
          備考: item.備考,
          承認状態: '未承認',
          作成者ID: item.作成者ID
        });

        if (saved) {
          item.synced = true;
          item.serverId = saved.作業記録ID;
        }
      } catch (error) {
        console.error('Sync error for item:', item.id, error);
        throw error;
      }
    }

    saveLocalData();
    updatePendingCount();
    renderLocalData();
  }

  // 自動保存の開始
  function startAutoSave() {
    if (autoSaveInterval) {
      clearInterval(autoSaveInterval);
    }

    autoSaveInterval = setInterval(performAutoSave, currentSaveInterval * 1000);
    updateAutoSaveStatus('success', '正常動作中');
  }

  // 自動保存の停止
  function stopAutoSave() {
    if (autoSaveInterval) {
      clearInterval(autoSaveInterval);
      autoSaveInterval = null;
    }
    updateAutoSaveStatus('warning', '停止中');
  }

  // 手動同期の実行
  async function performManualSync() {
    const btn = container.querySelector('#btn-manual-sync');
    const originalText = btn.textContent;

    try {
      btn.textContent = '同期中...';
      btn.disabled = true;

      if (!isOnline) {
        throw new Error('ネットワークに接続されていません');
      }

      await syncPendingData();

      // 成功通知
      updateAutoSaveStatus('success', '同期完了');
      setTimeout(() => {
        updateAutoSaveStatus('success', '正常動作中');
      }, 3000);

    } catch (error) {
      console.error('Manual sync error:', error);
      showError('手動同期に失敗しました: ' + error.message);
    } finally {
      btn.textContent = originalText;
      btn.disabled = false;
    }
  }

  // データ復旧の実行
  function performDataRecovery() {
    if (!confirm('ローカル保存データから復旧を実行しますか？')) {
      return;
    }

    try {
      // 復旧可能なデータを検索
      const recoveryData = pendingData.filter(item => !item.synced);

      if (recoveryData.length === 0) {
        alert('復旧可能なデータがありません。');
        return;
      }

      // 工数記録画面に遷移して復旧データを設定
      window.showScreen('scr-1778907133295');

      // 復旧データを一時的に保存（他画面で参照可能にする）
      sessionStorage.setItem('recoveryData', JSON.stringify(recoveryData[0]));

    } catch (error) {
      console.error('Data recovery error:', error);
      showError('データ復旧に失敗しました: ' + error.message);
    }
  }

  // 保存間隔の更新
  function updateSaveInterval() {
    const input = container.querySelector('#save-interval');
    const newInterval = parseInt(input.value);

    if (isNaN(newInterval) || newInterval < 1) {
      showError('保存間隔は1秒以上で設定してください');
      input.value = currentSaveInterval;
      return;
    }

    if (newInterval > 86400) {
      showError('保存間隔は86400秒（24時間）以下で設定してください');
      input.value = currentSaveInterval;
      return;
    }

    currentSaveInterval = newInterval;
    saveSettings();

    // 自動保存を再開
    startAutoSave();

    updateAutoSaveStatus('success', `保存間隔を${newInterval}秒に更新しました`);
    setTimeout(() => {
      updateAutoSaveStatus('success', '正常動作中');
    }, 3000);
  }

  // イベントリスナーの設定
  container.querySelector('#btn-update-interval').addEventListener('click', updateSaveInterval);
  container.querySelector('#btn-manual-sync').addEventListener('click', performManualSync);
  container.querySelector('#btn-data-recovery').addEventListener('click', performDataRecovery);

  container.querySelector('#btn-settings').addEventListener('click', () => {
    window.showScreen('scr-1778907133295'); // 工数記録画面（設定機能付き）
  });

  container.querySelector('#btn-back-to-main').addEventListener('click', () => {
    window.showScreen('scr-1778907133295'); // 工数記録画面
  });

  // ローカルデータの削除
  container.addEventListener('click', (e) => {
    const deleteBtn = e.target.closest('.delete-local-btn');
    if (deleteBtn) {
      const id = deleteBtn.dataset.id;
      if (confirm('このローカルデータを削除しますか？')) {
        pendingData = pendingData.filter(item => item.id !== id);
        saveLocalData();
        updatePendingCount();
        renderLocalData();
      }
    }
  });

  // ネットワーク状態の監視
  window.addEventListener('online', () => {
    isOnline = true;
    updateNetworkStatus();
    hideError();

    // オンライン復旧時の自動同期
    setTimeout(async () => {
      try {
        await syncPendingData();
        updateAutoSaveStatus('success', 'ネットワーク復旧 - 同期完了');
        setTimeout(() => {
          updateAutoSaveStatus('success', '正常動作中');
        }, 3000);
      } catch (error) {
        console.error('Auto sync on network recovery failed:', error);
      }
    }, 1000);
  });

  window.addEventListener('offline', () => {
    isOnline = false;
    updateNetworkStatus();
    showError('ネットワーク接続が切断されました。データはローカルに保存されます。');
  });

  // ストレージ容量チェック
  function checkStorageQuota() {
    if ('storage' in navigator && 'estimate' in navigator.storage) {
      navigator.storage.estimate().then(estimate => {
        const usageRatio = estimate.usage / estimate.quota;
        if (usageRatio > 0.9) {
          showError('端末の容量不足が検出されました。不要なファイルを削除してください。');
        }
      });
    }
  }

  // 初期化処理
  loadSettings();
  loadLocalData();
  updateNetworkStatus();
  startAutoSave();
  checkStorageQuota();

  // 定期的なストレージ容量チェック
  setInterval(checkStorageQuota, 60000); // 1分ごと
}

function(container, apiUrl, tables) {
  let mediaRecorder = null;
  let audioChunks = [];
  let currentWorkRecord = null;

  // DOM要素の取得
  const startTimeInput = container.querySelector('#start-time');
  const endTimeInput = container.querySelector('#end-time');
  const reasonSelect = container.querySelector('#reason');
  const locationInput = container.querySelector('#location');
  const detailsTextarea = container.querySelector('#details');
  const workItemDiv = container.querySelector('#work-item');
  const durationDiv = container.querySelector('#duration');
  const photoUpload = container.querySelector('#photo-upload');
  const photoBtn = container.querySelector('#photo-btn');
  const photoPreview = container.querySelector('#photo-preview');
  const recordBtn = container.querySelector('#record-btn');
  const stopBtn = container.querySelector('#stop-btn');
  const audioPreview = container.querySelector('#audio-preview');
  const errorMessage = container.querySelector('#error-message');
  const tempSaveBtn = container.querySelector('#temp-save-btn');
  const completeBtn = container.querySelector('#complete-btn');
  const charCount = container.querySelector('#char-count');
  const selectAllImpact = container.querySelector('#select-all-impact');

  // 現在時刻を中断開始時刻にセット
  const now = new Date();
  startTimeInput.value = now.toISOString().slice(0, 16);

  // 関連作業項目を取得・表示
  async function loadCurrentWorkRecord() {
    try {
      const workRecords = await window.aivicApi.list(1); // 作業記録テーブル
      if (workRecords) {
        const activeRecord = workRecords.find(r => r.進捗状況 === '作業中');
        if (activeRecord) {
          currentWorkRecord = activeRecord;
          workItemDiv.textContent = `${activeRecord.プロジェクト名} - ${activeRecord.作業種別}`;
        } else {
          workItemDiv.textContent = '進行中の作業がありません';
        }
      }
    } catch (error) {
      workItemDiv.textContent = '作業項目の取得に失敗しました';
    }
  }

  // 中断時間の自動計算
  function updateDuration() {
    const start = startTimeInput.value;
    const end = endTimeInput.value;

    if (start && end) {
      const startDate = new Date(start);
      const endDate = new Date(end);

      if (endDate > startDate) {
        const diffMs = endDate - startDate;
        const hours = Math.floor(diffMs / (1000 * 60 * 60));
        const minutes = Math.floor((diffMs % (1000 * 60 * 60)) / (1000 * 60));
        durationDiv.textContent = `${hours.toString().padStart(2, '0')}:${minutes.toString().padStart(2, '0')}`;
      } else {
        durationDiv.textContent = '--:--';
      }
    } else {
      durationDiv.textContent = '--:--';
    }
  }

  // 文字数カウント
  function updateCharCount() {
    const count = detailsTextarea.value.length;
    charCount.textContent = count;
    if (count > 1000) {
      charCount.style.color = '#fca5a5';
    } else {
      charCount.style.color = 'var(--text-muted)';
    }
  }

  // エラー表示
  function showError(message) {
    errorMessage.textContent = message;
    errorMessage.style.display = 'block';
    setTimeout(() => {
      errorMessage.style.display = 'none';
    }, 5000);
  }

  // バリデーション
  function validateForm() {
    const start = startTimeInput.value;
    const reason = reasonSelect.value;

    if (!start) {
      showError('中断開始時刻は必須です');
      return false;
    }

    if (!reason) {
      showError('中断理由は必須です');
      return false;
    }

    const startDate = new Date(start);
    const now = new Date();
    if (startDate > now) {
      showError('未来の時刻は入力できません');
      return false;
    }

    if (detailsTextarea.value.length > 1000) {
      showError('中断詳細は1000文字以内で入力してください');
      return false;
    }

    return true;
  }

  // フォームデータ収集
  function collectFormData() {
    const urgencyRadios = container.querySelectorAll('input[name="urgency"]:checked');
    const impactCheckboxes = container.querySelectorAll('input[name="impact"]:checked');

    const urgency = urgencyRadios.length > 0 ? urgencyRadios[0].value : null;
    const impacts = Array.from(impactCheckboxes).map(cb => cb.value);

    return {
      作業記録ID: currentWorkRecord ? currentWorkRecord.作業記録ID : null,
      中断開始日時: startTimeInput.value ? new Date(startTimeInput.value).toISOString() : null,
      中断終了日時: endTimeInput.value ? new Date(endTimeInput.value).toISOString() : null,
      中断理由区分: reasonSelect.value,
      中断理由詳細: detailsTextarea.value,
      中断時間: durationDiv.textContent !== '--:--' ? 
        parseInt(durationDiv.textContent.split(':')[0]) * 60 + parseInt(durationDiv.textContent.split(':')[1]) : null,
      影響度: urgency,
      対応状況: '対応中',
      記録者ID: 'current-user-id', // 実際の実装では認証情報から取得
      作成日時: new Date().toISOString(),
      更新日時: new Date().toISOString()
    };
  }

  // 一時保存
  async function tempSave() {
    const formData = collectFormData();
    localStorage.setItem('interruption_temp_data', JSON.stringify(formData));

    // 成功メッセージを一時的に表示
    const originalText = tempSaveBtn.textContent;
    tempSaveBtn.textContent = '保存済み';
    tempSaveBtn.style.background = 'var(--primary)';
    tempSaveBtn.style.color = '#fff';

    setTimeout(() => {
      tempSaveBtn.textContent = originalText;
      tempSaveBtn.style.background = 'transparent';
      tempSaveBtn.style.color = 'var(--text)';
    }, 2000);
  }

  // 一時保存データの復元
  function restoreTempData() {
    const tempData = localStorage.getItem('interruption_temp_data');
    if (tempData) {
      try {
        const data = JSON.parse(tempData);
        if (data.中断開始日時) {
          startTimeInput.value = new Date(data.中断開始日時).toISOString().slice(0, 16);
        }
        if (data.中断終了日時) {
          endTimeInput.value = new Date(data.中断終了日時).toISOString().slice(0, 16);
        }
        if (data.中断理由区分) {
          reasonSelect.value = data.中断理由区分;
        }
        if (data.中断理由詳細) {
          detailsTextarea.value = data.中断理由詳細;
        }
        if (data.影響度) {
          const urgencyRadio = container.querySelector(`input[name="urgency"][value="${data.影響度}"]`);
          if (urgencyRadio) urgencyRadio.checked = true;
        }
        updateDuration();
        updateCharCount();
      } catch (error) {
        console.error('一時保存データの復元に失敗:', error);
      }
    }
  }

  // 記録完了
  async function completeRecord() {
    if (!validateForm()) return;

    const formData = collectFormData();

    try {
      const saved = await window.aivicApi.save(2, formData); // 中断記録テーブル
      if (saved) {
        localStorage.removeItem('interruption_temp_data');
        window.showScreen("scr-1778907251446"); // 作業再開記録画面
      } else {
        showError('記録の保存に失敗しました');
      }
    } catch (error) {
      showError('ネットワークエラーが発生しました');
    }
  }

  // 影響範囲の全選択・全解除
  function updateSelectAll() {
    const impactCheckboxes = container.querySelectorAll('input[name="impact"]');
    const checkedBoxes = container.querySelectorAll('input[name="impact"]:checked');

    selectAllImpact.checked = impactCheckboxes.length === checkedBoxes.length;
    selectAllImpact.indeterminate = checkedBoxes.length > 0 && checkedBoxes.length < impactCheckboxes.length;
  }

  // イベントリスナー
  startTimeInput.addEventListener('change', updateDuration);
  endTimeInput.addEventListener('change', updateDuration);
  detailsTextarea.addEventListener('input', updateCharCount);

  // 写真添付
  photoBtn.addEventListener('click', () => {
    photoUpload.click();
  });

  photoUpload.addEventListener('change', (e) => {
    const file = e.target.files[0];
    if (file) {
      if (!file.type.startsWith('image/')) {
        showError('画像ファイルのみ添付可能です');
        return;
      }
      if (file.size > 10 * 1024 * 1024) { // 10MB
        showError('ファイルサイズは10MB以下にしてください');
        return;
      }
      photoPreview.textContent = `📷 ${file.name} (${(file.size / 1024 / 1024).toFixed(1)}MB)`;
    }
  });

  // 音声録音
  recordBtn.addEventListener('click', async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      mediaRecorder = new MediaRecorder(stream);
      audioChunks = [];

      mediaRecorder.ondataavailable = (event) => {
        audioChunks.push(event.data);
      };

      mediaRecorder.onstop = () => {
        const audioBlob = new Blob(audioChunks, { type: 'audio/wav' });
        audioPreview.textContent = `🎤 録音完了 (${(audioBlob.size / 1024).toFixed(1)}KB)`;
        stream.getTracks().forEach(track => track.stop());
      };

      mediaRecorder.start();
      recordBtn.disabled = true;
      stopBtn.disabled = false;
      recordBtn.textContent = '🎤 録音中...';

    } catch (error) {
      showError('録音の開始に失敗しました。マイクへのアクセスを許可してください。');
    }
  });

  stopBtn.addEventListener('click', () => {
    if (mediaRecorder && mediaRecorder.state === 'recording') {
      mediaRecorder.stop();
      recordBtn.disabled = false;
      stopBtn.disabled = true;
      recordBtn.textContent = '🎤 録音開始';
    }
  });

  // 影響範囲の全選択
  selectAllImpact.addEventListener('change', () => {
    const impactCheckboxes = container.querySelectorAll('input[name="impact"]');
    impactCheckboxes.forEach(cb => {
      cb.checked = selectAllImpact.checked;
    });
  });

  // 個別チェックボックスの変更
  container.addEventListener('change', (e) => {
    if (e.target.name === 'impact') {
      updateSelectAll();
    }
  });

  // ボタンイベント
  tempSaveBtn.addEventListener('click', tempSave);
  completeBtn.addEventListener('click', completeRecord);

  // ホバー効果
  photoBtn.addEventListener('mouseenter', () => {
    photoBtn.style.background = 'rgba(255,255,255,0.05)';
  });
  photoBtn.addEventListener('mouseleave', () => {
    photoBtn.style.background = 'transparent';
  });

  recordBtn.addEventListener('mouseenter', () => {
    if (!recordBtn.disabled) {
      recordBtn.style.background = 'rgba(255,255,255,0.05)';
    }
  });
  recordBtn.addEventListener('mouseleave', () => {
    if (!recordBtn.disabled) {
      recordBtn.style.background = 'transparent';
    }
  });

  tempSaveBtn.addEventListener('mouseenter', () => {
    tempSaveBtn.style.background = 'rgba(255,255,255,0.05)';
  });
  tempSaveBtn.addEventListener('mouseleave', () => {
    if (tempSaveBtn.textContent === '一時保存') {
      tempSaveBtn.style.background = 'transparent';
    }
  });

  completeBtn.addEventListener('mouseenter', () => {
    completeBtn.style.background = 'var(--primary-hover)';
  });
  completeBtn.addEventListener('mouseleave', () => {
    completeBtn.style.background = 'var(--primary)';
  });

  // 初期化
  loadCurrentWorkRecord();
  restoreTempData();
  updateCharCount();
}

function(container, apiUrl, tables) {
  let selectedWorkRecord = null;
  let suspendedWorks = [];

  // 現在時刻を設定
  function setCurrentTime() {
    const now = new Date();
    const localDateTime = new Date(now.getTime() - now.getTimezoneOffset() * 60000).toISOString().slice(0, 16);
    container.querySelector('#resume-time').value = localDateTime;
  }

  // 中断中作業の再描画
  function renderSuspendedWorks(works) {
    const tbody = container.querySelector('#suspended-works-tbody');
    const noMessage = container.querySelector('#no-suspended-message');
    const tableWrap = container.querySelector('#suspended-works-table-wrap');

    if (!works || works.length === 0) {
      noMessage.classList.remove('hidden');
      tableWrap.style.display = 'none';
      return;
    }

    noMessage.classList.add('hidden');
    tableWrap.style.display = 'block';

    tbody.innerHTML = works.map(work => {
      const suspendTime = work.中断開始日時 ? new Date(work.中断開始日時).toLocaleString() : '';
      return `
        <tr data-id="${work.作業記録ID}" style="cursor: pointer; height: 36px;" class="work-row">
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text); border-bottom: 1px solid rgba(255,255,255,0.05);">${work.プロジェクト名 || ''}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text); border-bottom: 1px solid rgba(255,255,255,0.05);">${suspendTime}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text); border-bottom: 1px solid rgba(255,255,255,0.05);">${work.中断理由詳細 || ''}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text); border-bottom: 1px solid rgba(255,255,255,0.05);">
            <button class="action-btn select-work-btn" data-id="${work.作業記録ID}" 
                    style="background: var(--primary); color: #fff; border: none; padding: 4px 8px; border-radius: 4px; font-size: 12px; cursor: pointer;">
              選択
            </button>
          </td>
        </tr>
      `;
    }).join('');
  }

  // 中断中作業を取得
  async function loadSuspendedWorks() {
    try {
      const workRecords = await window.aivicApi.list(1); // 作業記録テーブル
      const suspendRecords = await window.aivicApi.list(2); // 中断記録テーブル

      if (!workRecords || !suspendRecords) {
        renderSuspendedWorks([]);
        return;
      }

      // 中断中の作業を抽出（進捗状況が「中断」で中断終了日時がnullのもの）
      const suspended = workRecords.filter(work => 
        work.進捗状況 === '中断' && 
        suspendRecords.some(suspend => 
          suspend.作業記録ID === work.作業記録ID && !suspend.中断終了日時
        )
      );

      // 中断記録の詳細を付加
      const suspendedWithDetails = suspended.map(work => {
        const suspendRecord = suspendRecords.find(s => 
          s.作業記録ID === work.作業記録ID && !s.中断終了日時
        );
        return {
          ...work,
          中断開始日時: suspendRecord?.中断開始日時,
          中断理由詳細: suspendRecord?.中断理由詳細,
          中断記録ID: suspendRecord?.中断記録ID
        };
      });

      suspendedWorks = suspendedWithDetails;
      renderSuspendedWorks(suspendedWorks);
    } catch (error) {
      console.error('中断中作業の取得に失敗:', error);
      renderSuspendedWorks([]);
    }
  }

  // 作業選択
  function selectWork(workId) {
    selectedWorkRecord = suspendedWorks.find(w => w.作業記録ID === workId);
    if (!selectedWorkRecord) return;

    // 選択された作業の詳細を表示
    container.querySelector('#selected-work-name').textContent = selectedWorkRecord.プロジェクト名 || '';
    container.querySelector('#selected-suspend-time').textContent = 
      selectedWorkRecord.中断開始日時 ? new Date(selectedWorkRecord.中断開始日時).toLocaleString() : '';

    container.querySelector('#selected-work-details').classList.remove('hidden');
    container.querySelector('#resume-form').classList.remove('hidden');

    setCurrentTime();
  }

  // 文字数カウント更新
  function updateCharCount() {
    const textarea = container.querySelector('#resume-reason-detail');
    const charCount = container.querySelector('#char-count');
    charCount.textContent = textarea.value.length;
  }

  // バリデーション
  function validateForm() {
    const reasonDetail = container.querySelector('#resume-reason-detail').value.trim();
    const errorDiv = container.querySelector('#resume-reason-error');

    if (!reasonDetail) {
      errorDiv.textContent = '再開理由は必須です';
      errorDiv.classList.remove('hidden');
      return false;
    }

    if (reasonDetail.length > 500) {
      errorDiv.textContent = '再開理由は500文字以内で入力してください';
      errorDiv.classList.remove('hidden');
      return false;
    }

    errorDiv.classList.add('hidden');
    return true;
  }

  // 作業再開処理
  async function resumeWork() {
    if (!selectedWorkRecord || !validateForm()) return;

    const reasonSelect = container.querySelector('#resume-reason-select').value;
    const reasonDetail = container.querySelector('#resume-reason-detail').value.trim();
    const resumeTime = container.querySelector('#resume-time').value;

    try {
      // 作業記録を「作業中」に更新
      const updatedWork = await window.aivicApi.update(1, selectedWorkRecord.作業記録ID, {
        進捗状況: '作業中',
        更新日時: new Date().toISOString()
      });

      if (!updatedWork) {
        alert('作業記録の更新に失敗しました');
        return;
      }

      // 中断記録に終了時刻を設定
      if (selectedWorkRecord.中断記録ID) {
        await window.aivicApi.update(2, selectedWorkRecord.中断記録ID, {
          中断終了日時: new Date(resumeTime).toISOString(),
          対応状況: '解決済み',
          更新日時: new Date().toISOString()
        });
      }

      alert('作業を再開しました');

      // 工数入力画面に遷移
      window.showScreen("scr-1778907296658");

    } catch (error) {
      console.error('作業再開処理でエラー:', error);
      alert('作業再開に失敗しました');
    }
  }

  // ダイアログ表示
  function showConfirmDialog() {
    container.querySelector('#resume-confirm-dialog').classList.remove('hidden');
  }

  function hideConfirmDialog() {
    container.querySelector('#resume-confirm-dialog').classList.add('hidden');
  }

  // フォームリセット
  function resetForm() {
    selectedWorkRecord = null;
    container.querySelector('#selected-work-details').classList.add('hidden');
    container.querySelector('#resume-form').classList.add('hidden');
    container.querySelector('#resume-reason-select').value = '';
    container.querySelector('#resume-reason-detail').value = '';
    container.querySelector('#resume-reason-error').classList.add('hidden');
    updateCharCount();
  }

  // 初期化
  setCurrentTime();
  loadSuspendedWorks();

  // イベントリスナー
  container.addEventListener('click', (e) => {
    // 作業選択
    const selectBtn = e.target.closest('.select-work-btn');
    if (selectBtn) {
      const workId = selectBtn.dataset.id;
      selectWork(workId);
      return;
    }

    // 行クリックでも選択
    const workRow = e.target.closest('.work-row');
    if (workRow && !e.target.closest('button')) {
      const workId = workRow.dataset.id;
      selectWork(workId);
      return;
    }
  });

  // 再開理由選択時の自動入力
  container.querySelector('#resume-reason-select').addEventListener('change', (e) => {
    const selected = e.target.value;
    const detailTextarea = container.querySelector('#resume-reason-detail');

    if (selected && selected !== 'その他') {
      detailTextarea.value = selected;
      updateCharCount();
    }
  });

  // 文字数カウント
  container.querySelector('#resume-reason-detail').addEventListener('input', updateCharCount);

  // 作業再開ボタン
  container.querySelector('#btn-resume').addEventListener('click', () => {
    if (validateForm()) {
      showConfirmDialog();
    }
  });

  // キャンセルボタン
  container.querySelector('#btn-cancel').addEventListener('click', resetForm);

  // 戻るボタン
  container.querySelector('#btn-back').addEventListener('click', () => {
    window.showScreen("scr-1778907296658");
  });

  // ダイアログのOK/キャンセル
  container.querySelector('#dialog-ok').addEventListener('click', () => {
    hideConfirmDialog();
    resumeWork();
  });

  container.querySelector('#dialog-cancel').addEventListener('click', hideConfirmDialog);

  // ダイアログ背景クリックで閉じる
  container.querySelector('#resume-confirm-dialog').addEventListener('click', (e) => {
    if (e.target === e.currentTarget) {
      hideConfirmDialog();
    }
  });
}

function(container, apiUrl, tables) {
  let isRetrying = false;
  let errorData = {
    code: 'E001',
    message: 'データの処理中にエラーが発生しました。しばらく時間をおいて再度お試しください。',
    timestamp: new Date().toLocaleString('ja-JP', { 
      year: 'numeric', 
      month: '2-digit', 
      day: '2-digit', 
      hour: '2-digit', 
      minute: '2-digit', 
      second: '2-digit' 
    }),
    details: null,
    solution: '1. ページを再読み込みしてください\n2. 問題が続く場合は管理者にお問い合わせください'
  };

  // URLパラメータからエラー情報を取得
  const urlParams = new URLSearchParams(window.location.search);
  if (urlParams.get('error')) {
    try {
      const errorParam = JSON.parse(decodeURIComponent(urlParams.get('error')));
      errorData = { ...errorData, ...errorParam };
    } catch (e) {
      console.warn('エラーパラメータの解析に失敗:', e);
    }
  }

  // エラー情報を画面に反映
  function displayError() {
    container.querySelector('#error-message').textContent = errorData.message;
    container.querySelector('#error-code').textContent = errorData.code;
    container.querySelector('#error-time').textContent = `発生時刻: ${errorData.timestamp}`;

    if (errorData.solution) {
      container.querySelector('#solution-text').innerHTML = errorData.solution.replace(/\n/g, '<br>');
    }
  }

  // エラー詳細の取得
  async function loadErrorDetails() {
    try {
      if (!errorData.details) {
        // 模擬的なエラー詳細取得
        await new Promise(resolve => setTimeout(resolve, 500));

        if (!navigator.onLine) {
          throw new Error('ネットワーク接続がありません');
        }

        errorData.details = {
          stack: `Error: ${errorData.message}\n    at processWorkRecord (work-record.js:45:12)\n    at saveRecord (work-record.js:23:8)`,
          userAgent: navigator.userAgent,
          url: window.location.href,
          sessionId: 'sess_' + Math.random().toString(36).substr(2, 9)
        };
      }

      const detailContent = container.querySelector('#error-detail-content');
      detailContent.innerHTML = `
        <div><strong>エラー内容:</strong> ${errorData.message}</div>
        <div><strong>セッションID:</strong> ${errorData.details.sessionId}</div>
        <div><strong>発生URL:</strong> ${errorData.details.url}</div>
        <div style="margin-top: 8px;"><strong>スタックトレース:</strong></div>
        <pre style="font-size: 11px; margin: 4px 0; white-space: pre-wrap;">${errorData.details.stack}</pre>
      `;
    } catch (error) {
      const detailContent = container.querySelector('#error-detail-content');
      detailContent.textContent = 'エラーの詳細情報を取得できませんでした。ネットワーク接続を確認してください。';
    }
  }

  // ネットワーク状態の監視
  function checkNetworkStatus() {
    const networkStatus = container.querySelector('#network-status');
    if (!navigator.onLine) {
      networkStatus.classList.remove('hidden');
    } else {
      networkStatus.classList.add('hidden');
    }
  }

  // 再試行処理
  async function handleRetry() {
    if (isRetrying) return;

    isRetrying = true;
    const retryBtn = container.querySelector('#btn-retry');
    const originalText = retryBtn.textContent;

    retryBtn.textContent = '処理中...';
    retryBtn.disabled = true;

    try {
      // ネットワーク状態をチェック
      if (!navigator.onLine) {
        throw new Error('ネットワーク接続がありません');
      }

      // 模擬的な再試行処理
      await new Promise(resolve => setTimeout(resolve, 1000));

      // セッション確認
      const sessionValid = localStorage.getItem('userSession');
      if (!sessionValid) {
        // セッション切れの場合はログイン画面へ
        window.location.href = './login.html';
        return;
      }

      // 成功した場合は前の画面に戻る
      if (window.history.length > 1) {
        window.history.back();
      } else {
        window.showScreen('scr-1778907133295'); // 工数記録画面
      }

    } catch (error) {
      // 再試行失敗
      errorData.message = '再試行に失敗しました。' + error.message;
      displayError();
      checkNetworkStatus();
    } finally {
      retryBtn.textContent = originalText;
      retryBtn.disabled = false;
      isRetrying = false;
    }
  }

  // 管理者連絡処理
  async function handleContactAdmin() {
    try {
      // 管理者連絡機能の可用性チェック
      if (!navigator.onLine) {
        throw new Error('ネットワーク接続がありません');
      }

      // 連絡画面への遷移（実際の実装では専用画面を作成）
      const contactInfo = {
        errorCode: errorData.code,
        errorMessage: errorData.message,
        timestamp: errorData.timestamp,
        userId: localStorage.getItem('userId') || 'unknown'
      };

      // 緊急報告画面に遷移
      window.showScreen('scr-1778907330826');

    } catch (error) {
      alert('管理者連絡機能が利用できません。\n\n代替連絡先:\n電話: 03-1234-5678\nメール: admin@company.com');
    }
  }

  // イベントリスナーの設定
  container.querySelector('#btn-retry').addEventListener('click', handleRetry);

  container.querySelector('#btn-back').addEventListener('click', () => {
    if (window.history.length > 1) {
      window.history.back();
    } else {
      window.showScreen('scr-1778907133295'); // 工数記録画面
    }
  });

  container.querySelector('#btn-home').addEventListener('click', () => {
    window.showScreen('scr-1778907133295'); // 工数記録画面（ホーム）
  });

  container.querySelector('#btn-contact').addEventListener('click', handleContactAdmin);

  container.querySelector('#btn-toggle-details').addEventListener('click', async () => {
    const detailsDiv = container.querySelector('#error-details');
    const toggleBtn = container.querySelector('#btn-toggle-details');

    if (detailsDiv.classList.contains('hidden')) {
      detailsDiv.classList.remove('hidden');
      toggleBtn.textContent = 'エラー詳細を非表示';
      await loadErrorDetails();
    } else {
      detailsDiv.classList.add('hidden');
      toggleBtn.textContent = 'エラー詳細を表示';
    }
  });

  // ネットワーク状態の監視
  window.addEventListener('online', checkNetworkStatus);
  window.addEventListener('offline', checkNetworkStatus);

  // 初期化
  displayError();
  checkNetworkStatus();

  // 長いエラーメッセージの制限
  const messageEl = container.querySelector('#error-message');
  if (messageEl.textContent.length > 500) {
    messageEl.textContent = messageEl.textContent.substring(0, 497) + '...';
  }
}

function(container, apiUrl, tables) {
  let currentAnomalyData = [];
  let allAnomalyData = [];
  let isVerificationRunning = false;
  let currentEditingId = null;

  // 異常値検出結果の再描画関数
  function renderAnomalyRows(rows) {
    const tbody = container.querySelector("#anomaly-tbody");
    if (!rows || rows.length === 0) {
      tbody.innerHTML = '<tr><td colspan="9" style="text-align: center; padding: 20px; color: var(--text-muted);">異常値は検出されませんでした</td></tr>';
      return;
    }

    tbody.innerHTML = rows.map(r => `
      <tr data-id="${r.異常値検出ログID || r.id || ''}">
        <td style="padding: 6px 10px;">
          <input type="checkbox" class="anomaly-check" data-id="${r.異常値検出ログID || r.id || ''}" style="accent-color: var(--primary);">
        </td>
        <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${formatDateTime(r.検出日時 || r.createdAt || '')}</td>
        <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${r.ユーザー名 || r.userName || '不明'}</td>
        <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">
          <span style="padding: 2px 6px; border-radius: 4px; font-size: 11px; background: ${getErrorTypeColor(r.異常値種別 || r.errorType)}; color: #fff;">
            ${r.異常値種別 || r.errorType || ''}
          </span>
        </td>
        <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${r.検出項目 || r.detectionItem || ''}</td>
        <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${r.検出値 || r.detectedValue || ''}</td>
        <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">
          <span style="padding: 2px 6px; border-radius: 4px; font-size: 11px; background: ${getSeverityColor(r.重要度 || r.severity)}; color: #fff;">
            ${r.重要度 || r.severity || ''}
          </span>
        </td>
        <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">
          <span style="padding: 2px 6px; border-radius: 4px; font-size: 11px; background: ${getStatusColor(r.確認状況 || r.status)}; color: #fff;">
            ${r.確認状況 || r.status || '未確認'}
          </span>
        </td>
        <td style="padding: 6px 10px;">
          <button class="action-btn secondary correction-btn" data-id="${r.異常値検出ログID || r.id || ''}" style="font-size: 11px; padding: 4px 8px;">修正</button>
        </td>
      </tr>
    `).join("");
  }

  // 日時フォーマット関数
  function formatDateTime(dateStr) {
    if (!dateStr) return '';
    const date = new Date(dateStr);
    return date.toLocaleString('ja-JP', { 
      year: 'numeric', 
      month: '2-digit', 
      day: '2-digit', 
      hour: '2-digit', 
      minute: '2-digit' 
    });
  }

  // エラー種別の色を取得
  function getErrorTypeColor(type) {
    const colors = {
      '長時間作業': '#ef4444',
      '頻繁中断': '#f97316', 
      '工数超過': '#eab308',
      '時刻異常': '#8b5cf6',
      '必須項目不足': '#ec4899'
    };
    return colors[type] || '#6b7280';
  }

  // 重要度の色を取得
  function getSeverityColor(severity) {
    const colors = {
      '高': '#dc2626',
      '中': '#ea580c',
      '低': '#65a30d'
    };
    return colors[severity] || '#6b7280';
  }

  // 確認状況の色を取得
  function getStatusColor(status) {
    const colors = {
      '未確認': '#6b7280',
      '確認済み': '#2563eb',
      '対応済み': '#16a34a'
    };
    return colors[status] || '#6b7280';
  }

  // 検証進捗の表示
  function showProgress() {
    const progressArea = container.querySelector("#progress-area");
    const progressBar = container.querySelector("#progress-bar");
    const progressText = container.querySelector("#progress-text");

    progressArea.classList.remove("hidden");

    let progress = 0;
    const interval = setInterval(() => {
      progress += Math.random() * 15;
      if (progress >= 100) {
        progress = 100;
        clearInterval(interval);
        setTimeout(() => {
          progressArea.classList.add("hidden");
          showCompletionNotice();
        }, 500);
      }
      progressBar.style.width = progress + "%";
      progressText.textContent = Math.round(progress) + "%";
    }, 200);
  }

  // 検証完了通知の表示
  function showCompletionNotice() {
    const notice = container.querySelector("#completion-notice");
    notice.classList.remove("hidden");
    setTimeout(() => {
      notice.classList.add("hidden");
    }, 3000);
  }

  // フィルター適用
  function applyFilters() {
    const errorType = container.querySelector("#filter-error-type").value;
    const severity = container.querySelector("#filter-severity").value;

    let filtered = allAnomalyData;

    if (errorType) {
      filtered = filtered.filter(r => (r.異常値種別 || r.errorType) === errorType);
    }

    if (severity) {
      filtered = filtered.filter(r => (r.重要度 || r.severity) === severity);
    }

    currentAnomalyData = filtered;
    renderAnomalyRows(currentAnomalyData);
  }

  // モーダルを開く
  function openCorrectionModal(anomalyId) {
    const anomaly = allAnomalyData.find(r => (r.異常値検出ログID || r.id) === anomalyId);
    if (!anomaly) return;

    currentEditingId = anomalyId;
    const modal = container.querySelector("#correction-modal");

    container.querySelector("#input-correction-item").value = anomaly.検出項目 || anomaly.detectionItem || '';
    container.querySelector("#input-current-value").value = anomaly.検出値 || anomaly.detectedValue || '';
    container.querySelector("#input-correction-value").value = '';
    container.querySelector("#input-correction-reason").value = '';

    modal.classList.remove("hidden");
  }

  // モーダルを閉じる
  function closeCorrectionModal() {
    const modal = container.querySelector("#correction-modal");
    modal.classList.add("hidden");
    currentEditingId = null;
  }

  // 初期データの描画
  if (tables[4] && tables[4].records) {
    allAnomalyData = tables[4].records;
    currentAnomalyData = allAnomalyData;
    renderAnomalyRows(currentAnomalyData);
  }

  // 検証実行ボタン
  container.querySelector("#btn-execute-verify").addEventListener("click", async () => {
    if (isVerificationRunning) {
      alert("検証処理が実行中です。しばらくお待ちください。");
      return;
    }

    const startDate = container.querySelector("#input-start-date").value;
    const endDate = container.querySelector("#input-end-date").value;

    if (!startDate || !endDate) {
      alert("検証対象期間を選択してください。");
      return;
    }

    if (new Date(startDate) > new Date(endDate)) {
      alert("開始日は終了日より前の日付を選択してください。");
      return;
    }

    // 1年以上の期間チェック
    const daysDiff = (new Date(endDate) - new Date(startDate)) / (1000 * 60 * 60 * 24);
    if (daysDiff > 365) {
      if (!confirm("1年以上の長期間が選択されています。処理に時間がかかる場合があります。続行しますか？")) {
        return;
      }
    }

    isVerificationRunning = true;
    container.querySelector("#btn-execute-verify").disabled = true;

    showProgress();

    try {
      // 検証処理をシミュレート
      setTimeout(async () => {
        const rows = await window.aivicApi.list(4);
        if (rows) {
          allAnomalyData = rows;
          currentAnomalyData = allAnomalyData;
          renderAnomalyRows(currentAnomalyData);
        }
        isVerificationRunning = false;
        container.querySelector("#btn-execute-verify").disabled = false;
      }, 3000);

    } catch (error) {
      console.error("検証処理エラー:", error);
      isVerificationRunning = false;
      container.querySelector("#btn-execute-verify").disabled = false;
      alert("検証処理中にエラーが発生しました。");
    }
  });

  // フィルター適用ボタン
  container.querySelector("#btn-apply-filter").addEventListener("click", applyFilters);

  // 全選択チェックボックス
  container.querySelector("#check-bulk-all").addEventListener("change", (e) => {
    const checkboxes = container.querySelectorAll(".anomaly-check");
    checkboxes.forEach(cb => cb.checked = e.target.checked);
  });

  // 一括承認ボタン
  container.querySelector("#btn-bulk-approve").addEventListener("click", async () => {
    const checkedBoxes = container.querySelectorAll(".anomaly-check:checked");
    if (checkedBoxes.length === 0) {
      alert("承認する項目を選択してください。");
      return;
    }

    if (!confirm(`選択した${checkedBoxes.length}件のデータを一括承認しますか？`)) {
      return;
    }

    try {
      for (const checkbox of checkedBoxes) {
        const id = checkbox.dataset.id;
        await window.aivicApi.update(4, id, { 確認状況: '対応済み', 確認日時: new Date().toISOString() });
      }

      const rows = await window.aivicApi.list(4);
      if (rows) {
        allAnomalyData = rows;
        applyFilters();
      }

      alert("一括承認が完了しました。");
      container.querySelector("#check-bulk-all").checked = false;

    } catch (error) {
      console.error("一括承認エラー:", error);
      alert("一括承認中にエラーが発生しました。");
    }
  });

  // 検証ログ出力ボタン
  container.querySelector("#btn-export-log").addEventListener("click", async () => {
    try {
      const rows = await window.aivicApi.list(4);
      if (!rows || rows.length === 0) {
        alert("検証結果がありません。先にデータ検証を実行してください。");
        return;
      }

      const headers = ['検出日時', '作業員', '異常値種別', '検出項目', '検出値', '重要度', '確認状況', '対応メモ'];
      const csvData = [
        headers.join(','),
        ...rows.map(r => [
          formatDateTime(r.検出日時 || r.createdAt || ''),
          r.ユーザー名 || r.userName || '',
          r.異常値種別 || r.errorType || '',
          r.検出項目 || r.detectionItem || '',
          r.検出値 || r.detectedValue || '',
          r.重要度 || r.severity || '',
          r.確認状況 || r.status || '',
          r.対応メモ || r.memo || ''
        ].map(field => `"${String(field).replace(/"/g, '""')}"`).join(','))
      ].join('\n');

      const blob = new Blob(['\uFEFF' + csvData], { type: 'text/csv;charset=utf-8;' });
      const link = document.createElement('a');
      link.href = URL.createObjectURL(blob);
      link.download = `verification_log_${new Date().toISOString().split('T')[0]}.csv`;
      link.click();

    } catch (error) {
      console.error("ログ出力エラー:", error);
      alert("ログ出力中にエラーが発生しました。");
    }
  });

  // 再検証ボタン
  container.querySelector("#btn-re-verify").addEventListener("click", () => {
    if (!confirm("再検証を実行しますか？")) return;

    // 検証実行と同じ処理を呼び出し
    container.querySelector("#btn-execute-verify").click();
  });

  // モーダル関連のイベント
  container.querySelector("#btn-close-modal").addEventListener("click", closeCorrectionModal);
  container.querySelector("#btn-cancel-correction").addEventListener("click", closeCorrectionModal);

  // 修正保存ボタン
  container.querySelector("#btn-save-correction").addEventListener("click", async () => {
    const correctionValue = container.querySelector("#input-correction-value").value.trim();
    const correctionReason = container.querySelector("#input-correction-reason").value.trim();

    if (!correctionValue) {
      alert("修正値を入力してください。");
      return;
    }

    // 修正データの妥当性チェック
    const detectionItem = container.querySelector("#input-correction-item").value;
    if (detectionItem.includes('時間') && (isNaN(correctionValue) || correctionValue < 0 || correctionValue > 24)) {
      alert("修正データが不正です。作業時間は0-24時間の範囲で入力してください。");
      return;
    }

    try {
      await window.aivicApi.update(4, currentEditingId, {
        検出値: correctionValue,
        確認状況: '対応済み',
        対応メモ: correctionReason,
        確認日時: new Date().toISOString()
      });

      const rows = await window.aivicApi.list(4);
      if (rows) {
        allAnomalyData = rows;
        applyFilters();
      }

      closeCorrectionModal();
      alert("データの修正が完了しました。");

    } catch (error) {
      console.error("修正保存エラー:", error);
      alert("修正保存中にエラーが発生しました。");
    }
  });

  // イベントデリゲーション（修正ボタン）
  container.addEventListener("click", (e) => {
    const correctionBtn = e.target.closest(".correction-btn");
    if (correctionBtn) {
      const id = correctionBtn.dataset.id;
      openCorrectionModal(id);
    }
  });

  // モーダル背景クリックで閉じる
  container.querySelector("#correction-modal").addEventListener("click", (e) => {
    if (e.target === e.currentTarget) {
      closeCorrectionModal();
    }
  });
}

function(container, apiUrl, tables) {
  let currentRecord = null;
  let workItems = [];
  let breakRecords = [];

  // DOM要素取得
  const targetRecordSelect = container.querySelector('#target-record-select');
  const originalDataArea = container.querySelector('#original-data-area');
  const originalDataContent = container.querySelector('#original-data-content');
  const editForm = container.querySelector('#edit-form');
  const workDateInput = container.querySelector('#work-date');
  const workItemSelect = container.querySelector('#work-item');
  const startTimeInput = container.querySelector('#start-time');
  const endTimeInput = container.querySelector('#end-time');
  const breakTimeInput = container.querySelector('#break-time');
  const breakReasonSelect = container.querySelector('#break-reason');
  const breakDurationDiv = container.querySelector('#break-duration');
  const actualWorkTimeDiv = container.querySelector('#actual-work-time');
  const correctionReasonTextarea = container.querySelector('#correction-reason');
  const reasonCharCount = container.querySelector('#reason-char-count');
  const warningArea = container.querySelector('#warning-area');
  const warningList = container.querySelector('#warning-list');
  const errorArea = container.querySelector('#error-area');
  const errorMessage = container.querySelector('#error-message');
  const cancelBtn = container.querySelector('#cancel-btn');
  const saveBtn = container.querySelector('#save-btn');

  // 初期データ読み込み
  async function loadInitialData() {
    try {
      // 作業記録一覧を取得
      const workRecords = await window.aivicApi.list(1) || tables[1]?.records || [];

      // 作業項目マスタを取得
      workItems = await window.aivicApi.list(3) || tables[3]?.records || [];

      // 中断記録を取得
      breakRecords = await window.aivicApi.list(2) || tables[2]?.records || [];

      // 修正対象記録のドロップダウンを更新
      targetRecordSelect.innerHTML = '<option value="">記録を選択してください</option>';
      workRecords.forEach(record => {
        const option = document.createElement('option');
        option.value = record.作業記録ID || record.id;
        option.textContent = `${record.作業日 || '未設定'} - ${record.作業内容 || '作業内容未設定'} (${record.作業員ID || 'ID未設定'})`;
        targetRecordSelect.appendChild(option);
      });

      // 作業項目のドロップダウンを更新
      workItemSelect.innerHTML = '<option value="">選択してください</option>';
      workItems
        .filter(item => item.有効フラグ !== false)
        .sort((a, b) => (a.表示順序 || 0) - (b.表示順序 || 0))
        .forEach(item => {
          const option = document.createElement('option');
          option.value = item.作業項目ID || item.id;
          option.textContent = `${item.作業項目コード || ''} - ${item.作業項目名 || ''}`;
          workItemSelect.appendChild(option);
        });

    } catch (error) {
      console.error('初期データ読み込みエラー:', error);
    }
  }

  // 修正対象記録選択時の処理
  targetRecordSelect.addEventListener('change', async function() {
    const recordId = this.value;
    if (!recordId) {
      originalDataArea.classList.add('hidden');
      editForm.classList.add('hidden');
      currentRecord = null;
      return;
    }

    try {
      // 選択された記録の詳細を取得
      const workRecords = await window.aivicApi.list(1) || [];
      currentRecord = workRecords.find(r => (r.作業記録ID || r.id) === recordId);

      if (!currentRecord) {
        showError('選択された記録が見つかりません');
        return;
      }

      // 修正前データを表示
      displayOriginalData(currentRecord);

      // フォームに現在の値を設定
      populateForm(currentRecord);

      // フォームを表示
      originalDataArea.classList.remove('hidden');
      editForm.classList.remove('hidden');

    } catch (error) {
      console.error('記録取得エラー:', error);
      showError('記録の取得に失敗しました');
    }
  });

  // 修正前データ表示
  function displayOriginalData(record) {
    const startTime = record.作業開始時刻 ? new Date(record.作業開始時刻).toLocaleTimeString('ja-JP', {hour: '2-digit', minute: '2-digit'}) : '未設定';
    const endTime = record.作業終了時刻 ? new Date(record.作業終了時刻).toLocaleTimeString('ja-JP', {hour: '2-digit', minute: '2-digit'}) : '未設定';
    const workDate = record.作業日 ? new Date(record.作業日).toLocaleDateString('ja-JP') : '未設定';

    originalDataContent.innerHTML = `
      <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 8px; font-size: 12px;">
        <div><strong>作業日:</strong> ${workDate}</div>
        <div><strong>作業時間:</strong> ${record.作業時間 || 0}分</div>
        <div><strong>開始時刻:</strong> ${startTime}</div>
        <div><strong>終了時刻:</strong> ${endTime}</div>
        <div><strong>作業内容:</strong> ${record.作業内容 || '未設定'}</div>
        <div><strong>進捗状況:</strong> ${record.進捗状況 || '未設定'}</div>
      </div>
    `;
  }

  // フォームに値を設定
  function populateForm(record) {
    // 作業日
    if (record.作業日) {
      const date = new Date(record.作業日);
      workDateInput.value = date.toISOString().split('T')[0];
    }

    // 作業開始・終了時刻
    if (record.作業開始時刻) {
      const startDate = new Date(record.作業開始時刻);
      startTimeInput.value = startDate.toTimeString().slice(0, 5);
    }
    if (record.作業終了時刻) {
      const endDate = new Date(record.作業終了時刻);
      endTimeInput.value = endDate.toTimeString().slice(0, 5);
    }

    // 作業項目（作業内容から推測）
    const matchingItem = workItems.find(item => 
      item.作業項目名 === record.作業内容 || 
      item.作業項目コード === record.作業種別
    );
    if (matchingItem) {
      workItemSelect.value = matchingItem.作業項目ID || matchingItem.id;
    }

    // 中断記録があれば設定
    const relatedBreak = breakRecords.find(br => br.作業記録ID === (record.作業記録ID || record.id));
    if (relatedBreak) {
      if (relatedBreak.中断開始日時) {
        const breakDate = new Date(relatedBreak.中断開始日時);
        breakTimeInput.value = breakDate.toTimeString().slice(0, 5);
      }
      if (relatedBreak.中断理由区分) {
        breakReasonSelect.value = relatedBreak.中断理由区分;
      }
    }

    // 時間計算を更新
    calculateTimes();
  }

  // 時間計算
  function calculateTimes() {
    const startTime = startTimeInput.value;
    const endTime = endTimeInput.value;
    const breakTime = breakTimeInput.value;

    let breakDuration = 0;
    let actualWorkTime = 0;

    if (startTime && endTime) {
      const start = new Date(`2000-01-01T${startTime}:00`);
      const end = new Date(`2000-01-01T${endTime}:00`);

      if (end > start) {
        const totalMinutes = (end - start) / (1000 * 60);

        if (breakTime) {
          const breakStart = new Date(`2000-01-01T${breakTime}:00`);
          if (breakStart >= start && breakStart <= end) {
            // 簡易的に30分の中断と仮定
            breakDuration = 30;
          }
        }

        actualWorkTime = totalMinutes - breakDuration;
      }
    }

    breakDurationDiv.textContent = `${breakDuration}分`;

    const hours = Math.floor(actualWorkTime / 60);
    const minutes = actualWorkTime % 60;
    actualWorkTimeDiv.textContent = `${hours}時間${minutes}分`;
  }

  // 入力フィールドの変更監視
  [startTimeInput, endTimeInput, breakTimeInput].forEach(input => {
    input.addEventListener('change', calculateTimes);
  });

  // 修正理由の文字数カウント
  correctionReasonTextarea.addEventListener('input', function() {
    const length = this.value.length;
    reasonCharCount.textContent = length;

    if (length > 200) {
      this.value = this.value.substring(0, 200);
      reasonCharCount.textContent = '200';
    }
  });

  // バリデーション
  function validateForm() {
    const errors = [];
    const warnings = [];

    // 修正対象記録の選択チェック
    if (!currentRecord) {
      errors.push('修正対象の記録を選択してください');
    }

    // 作業日付チェック
    const workDate = workDateInput.value;
    if (!workDate) {
      errors.push('作業日付を入力してください');
    } else {
      const date = new Date(workDate);
      const today = new Date();
      const minDate = new Date('1900-01-01');
      const maxDate = new Date('2099-12-31');

      if (date < minDate || date > maxDate) {
        errors.push('作業日付は1900年1月1日から2099年12月31日の範囲で入力してください');
      }

      if (date > today) {
        warnings.push('未来の日付が入力されています');
      }
    }

    // 時刻チェック
    const startTime = startTimeInput.value;
    const endTime = endTimeInput.value;

    if (startTime && endTime) {
      const start = new Date(`2000-01-01T${startTime}:00`);
      const end = new Date(`2000-01-01T${endTime}:00`);

      if (start >= end) {
        errors.push('開始時刻は終了時刻より前の時刻を入力してください');
      }

      const totalHours = (end - start) / (1000 * 60 * 60);
      if (totalHours > 20) {
        warnings.push('20時間を超える長時間作業が入力されています');
      }
    }

    // 中断時刻チェック
    const breakTime = breakTimeInput.value;
    if (breakTime && startTime && endTime) {
      const breakStart = new Date(`2000-01-01T${breakTime}:00`);
      const start = new Date(`2000-01-01T${startTime}:00`);
      const end = new Date(`2000-01-01T${endTime}:00`);

      if (breakStart < start || breakStart > end) {
        errors.push('中断時刻は作業時間内で入力してください');
      }
    }

    // 修正理由チェック
    const reason = correctionReasonTextarea.value.trim();
    if (!reason) {
      errors.push('修正理由を入力してください');
    }

    return { errors, warnings };
  }

  // エラー表示
  function showError(message) {
    errorMessage.textContent = message;
    errorArea.classList.remove('hidden');
  }

  // エラー非表示
  function hideError() {
    errorArea.classList.add('hidden');
  }

  // 警告表示
  function showWarnings(warnings) {
    if (warnings.length > 0) {
      warningList.innerHTML = warnings.map(w => `<li>${w}</li>`).join('');
      warningArea.classList.remove('hidden');
    } else {
      warningArea.classList.add('hidden');
    }
  }

  // 保存処理
  saveBtn.addEventListener('click', async function() {
    hideError();

    const validation = validateForm();

    if (validation.errors.length > 0) {
      showError(validation.errors.join('\n'));
      return;
    }

    showWarnings(validation.warnings);

    try {
      // 作業記録の更新
      const updatedRecord = {
        作業日: workDateInput.value,
        作業開始時刻: workDateInput.value + 'T' + (startTimeInput.value || '00:00') + ':00',
        作業終了時刻: endTimeInput.value ? workDateInput.value + 'T' + endTimeInput.value + ':00' : null,
        作業内容: workItemSelect.options[workItemSelect.selectedIndex]?.text || currentRecord.作業内容,
        作業種別: workItemSelect.value || currentRecord.作業種別,
        更新日時: new Date().toISOString(),
        更新者ID: 'current-user' // 実際の実装では現在のユーザーIDを使用
      };

      // 作業時間を再計算
      if (updatedRecord.作業開始時刻 && updatedRecord.作業終了時刻) {
        const start = new Date(updatedRecord.作業開始時刻);
        const end = new Date(updatedRecord.作業終了時刻);
        const breakDuration = breakTimeInput.value ? 30 : 0; // 簡易的に30分と仮定
        updatedRecord.作業時間 = Math.max(0, (end - start) / (1000 * 60) - breakDuration);
      }

      const result = await window.aivicApi.update(1, currentRecord.作業記録ID || currentRecord.id, updatedRecord);

      if (result) {
        // 中断記録の処理
        if (breakTimeInput.value && breakReasonSelect.value) {
          const breakRecord = {
            作業記録ID: currentRecord.作業記録ID || currentRecord.id,
            中断開始日時: workDateInput.value + 'T' + breakTimeInput.value + ':00',
            中断理由区分: breakReasonSelect.value,
            中断理由詳細: correctionReasonTextarea.value,
            記録者ID: 'current-user',
            作成日時: new Date().toISOString(),
            更新日時: new Date().toISOString()
          };

          const existingBreak = breakRecords.find(br => br.作業記録ID === (currentRecord.作業記録ID || currentRecord.id));
          if (existingBreak) {
            await window.aivicApi.update(2, existingBreak.中断記録ID || existingBreak.id, breakRecord);
          } else {
            await window.aivicApi.save(2, breakRecord);
          }
        }

        alert('修正が正常に保存されました');

        // フォームをリセット
        targetRecordSelect.value = '';
        originalDataArea.classList.add('hidden');
        editForm.classList.add('hidden');
        currentRecord = null;

        // 作業履歴一覧画面に遷移
        window.showScreen('scr-1778907145716');

      } else {
        showError('保存に失敗しました');
      }

    } catch (error) {
      console.error('保存エラー:', error);
      showError('保存中にエラーが発生しました');
    }
  });

  // キャンセル処理
  cancelBtn.addEventListener('click', function() {
    if (confirm('修正内容を破棄して作業履歴一覧に戻りますか？')) {
      window.showScreen('scr-1778907145716');
    }
  });

  // 初期データ読み込み実行
  loadInitialData();
}

function(container, apiUrl, tables) {
  let selectedPriority = '';
  let attachedFiles = [];

  // 現在のユーザー情報を設定（仮の値）
  const currentUser = {
    name: '田中太郎',
    phone: '090-1234-5678'
  };

  // 報告者名を自動設定
  const reporterNameInput = container.querySelector('#reporter-name');
  reporterNameInput.value = currentUser.name;

  // 作業項目のオプションを設定
  const workItemSelect = container.querySelector('#work-item');
  if (tables[3] && tables[3].records) {
    tables[3].records.forEach(item => {
      const option = document.createElement('option');
      option.value = item.作業項目ID || item.id;
      option.textContent = item.作業項目名 || item.name;
      workItemSelect.appendChild(option);
    });
  }

  // 緊急度選択ボタンのイベント
  container.addEventListener('click', (e) => {
    if (e.target.classList.contains('priority-btn')) {
      // 全ボタンのスタイルをリセット
      container.querySelectorAll('.priority-btn').forEach(btn => {
        btn.style.background = 'transparent';
        btn.style.color = 'var(--text)';
      });

      // 選択されたボタンをハイライト
      e.target.style.background = 'var(--primary)';
      e.target.style.color = '#fff';
      selectedPriority = e.target.dataset.priority;

      // エラーメッセージをクリア
      const errorDiv = container.querySelector('#priority-error');
      errorDiv.style.display = 'none';
    }
  });

  // 文字数カウンター
  const emergencyContent = container.querySelector('#emergency-content');
  const charCount = container.querySelector('#char-count');
  emergencyContent.addEventListener('input', () => {
    const length = emergencyContent.value.length;
    charCount.textContent = `(${length}/1000)`;

    if (length > 1000) {
      charCount.style.color = '#dc2626';
      const errorDiv = container.querySelector('#emergency-content-error');
      errorDiv.textContent = '文字数上限を超えています（1000文字以内）';
      errorDiv.style.display = 'block';
    } else {
      charCount.style.color = 'var(--text-muted)';
      const errorDiv = container.querySelector('#emergency-content-error');
      errorDiv.style.display = 'none';
    }
  });

  // 写真アップロード機能
  const photoUploadArea = container.querySelector('#photo-upload-area');
  const photoInput = container.querySelector('#photo-input');
  const photoPreview = container.querySelector('#photo-preview');
  const photoError = container.querySelector('#photo-error');

  photoUploadArea.addEventListener('click', () => {
    photoInput.click();
  });

  photoUploadArea.addEventListener('dragover', (e) => {
    e.preventDefault();
    photoUploadArea.style.borderColor = 'var(--primary)';
  });

  photoUploadArea.addEventListener('dragleave', () => {
    photoUploadArea.style.borderColor = 'rgba(255,255,255,0.18)';
  });

  photoUploadArea.addEventListener('drop', (e) => {
    e.preventDefault();
    photoUploadArea.style.borderColor = 'rgba(255,255,255,0.18)';
    handleFiles(e.dataTransfer.files);
  });

  photoInput.addEventListener('change', (e) => {
    handleFiles(e.target.files);
  });

  function handleFiles(files) {
    photoError.style.display = 'none';

    for (let file of files) {
      if (attachedFiles.length >= 5) {
        photoError.textContent = '画像は最大5枚まで添付できます';
        photoError.style.display = 'block';
        break;
      }

      if (!file.type.startsWith('image/')) {
        photoError.textContent = 'サポートされていないファイル形式です。JPG、PNG形式のファイルをアップロードしてください。';
        photoError.style.display = 'block';
        continue;
      }

      if (file.size > 5 * 1024 * 1024) {
        photoError.textContent = 'ファイルサイズが上限を超えています（5MB以内）';
        photoError.style.display = 'block';
        continue;
      }

      attachedFiles.push(file);

      const reader = new FileReader();
      reader.onload = (e) => {
        const previewDiv = document.createElement('div');
        previewDiv.style.cssText = 'position: relative; display: inline-block;';
        previewDiv.innerHTML = `
          <img src="${e.target.result}" style="width: 80px; height: 80px; object-fit: cover; border-radius: 4px; border: 1px solid rgba(255,255,255,0.18);">
          <button type="button" class="remove-photo" data-index="${attachedFiles.length - 1}" style="position: absolute; top: -4px; right: -4px; width: 20px; height: 20px; border-radius: 50%; background: #dc2626; color: #fff; border: none; font-size: 12px; cursor: pointer; display: flex; align-items: center; justify-content: center;">×</button>
        `;
        photoPreview.appendChild(previewDiv);
      };
      reader.readAsDataURL(file);
    }
  }

  // 写真削除
  container.addEventListener('click', (e) => {
    if (e.target.classList.contains('remove-photo')) {
      const index = parseInt(e.target.dataset.index);
      attachedFiles.splice(index, 1);
      e.target.closest('div').remove();

      // インデックスを再設定
      container.querySelectorAll('.remove-photo').forEach((btn, i) => {
        btn.dataset.index = i;
      });
    }
  });

  // バリデーション関数
  function validateForm() {
    let isValid = true;

    // 緊急度チェック
    if (!selectedPriority) {
      const errorDiv = container.querySelector('#priority-error');
      errorDiv.textContent = '緊急度を選択してください';
      errorDiv.style.display = 'block';
      isValid = false;
    }

    // 報告種別チェック
    const reportType = container.querySelector('#report-type').value;
    if (!reportType) {
      const errorDiv = container.querySelector('#report-type-error');
      errorDiv.textContent = '報告種別を選択してください';
      errorDiv.style.display = 'block';
      isValid = false;
    }

    // 発生日時チェック
    const occurrenceDateTime = container.querySelector('#occurrence-datetime').value;
    if (!occurrenceDateTime) {
      const errorDiv = container.querySelector('#occurrence-datetime-error');
      errorDiv.textContent = '発生日時を入力してください';
      errorDiv.style.display = 'block';
      isValid = false;
    } else {
      const inputDate = new Date(occurrenceDateTime);
      const now = new Date();
      if (inputDate > now) {
        const errorDiv = container.querySelector('#occurrence-datetime-error');
        errorDiv.textContent = '発生日時に未来の日付は入力できません';
        errorDiv.style.display = 'block';
        isValid = false;
      }
    }

    // 発生場所チェック
    const occurrenceLocation = container.querySelector('#occurrence-location').value;
    if (!occurrenceLocation.trim()) {
      const errorDiv = container.querySelector('#occurrence-location-error');
      errorDiv.textContent = '発生場所を入力してください';
      errorDiv.style.display = 'block';
      isValid = false;
    }

    // 緊急事態内容チェック
    const emergencyContent = container.querySelector('#emergency-content').value;
    if (!emergencyContent.trim()) {
      const errorDiv = container.querySelector('#emergency-content-error');
      errorDiv.textContent = '緊急事態内容を入力してください';
      errorDiv.style.display = 'block';
      isValid = false;
    } else if (emergencyContent.length > 1000) {
      const errorDiv = container.querySelector('#emergency-content-error');
      errorDiv.textContent = '文字数上限を超えています（1000文字以内）';
      errorDiv.style.display = 'block';
      isValid = false;
    }

    // 連絡先電話番号チェック
    const contactPhone = container.querySelector('#contact-phone').value;
    if (!contactPhone.trim()) {
      const errorDiv = container.querySelector('#contact-phone-error');
      errorDiv.textContent = '連絡先電話番号を入力してください';
      errorDiv.style.display = 'block';
      isValid = false;
    } else {
      const phonePattern = /^0\d{1,4}-\d{1,4}-\d{4}$/;
      if (!phonePattern.test(contactPhone)) {
        const errorDiv = container.querySelector('#contact-phone-error');
        errorDiv.textContent = '正しい電話番号の形式で入力してください（例：090-1234-5678）';
        errorDiv.style.display = 'block';
        isValid = false;
      }
    }

    return isValid;
  }

  // エラーメッセージをクリア
  function clearErrors() {
    container.querySelectorAll('.error-message').forEach(error => {
      error.style.display = 'none';
    });
  }

  // フォームデータを収集
  function collectFormData() {
    return {
      緊急度: selectedPriority,
      報告種別: container.querySelector('#report-type').value,
      発生日時: container.querySelector('#occurrence-datetime').value,
      発生場所: container.querySelector('#occurrence-location').value,
      作業項目ID: container.querySelector('#work-item').value,
      緊急事態内容: container.querySelector('#emergency-content').value,
      報告者名: container.querySelector('#reporter-name').value,
      連絡先電話番号: container.querySelector('#contact-phone').value,
      添付ファイル数: attachedFiles.length,
      報告日時: new Date().toISOString(),
      状態: '報告済み'
    };
  }

  // 下書き保存ボタン
  container.querySelector('#btn-draft').addEventListener('click', async () => {
    const formData = collectFormData();
    formData.状態 = '下書き';

    try {
      const saved = await window.aivicApi.save(0, formData);
      if (saved) {
        alert('下書きを保存しました');
      }
    } catch (error) {
      alert('下書きの保存に失敗しました');
    }
  });

  // 即座に報告ボタン
  container.querySelector('#btn-submit').addEventListener('click', async () => {
    clearErrors();

    if (!validateForm()) {
      return;
    }

    const formData = collectFormData();

    try {
      const saved = await window.aivicApi.save(0, formData);
      if (saved) {
        alert('緊急報告を送信しました。関係者に通知されます。');
        // フォームをリセット
        container.querySelector('#emergency-form').reset();
        selectedPriority = '';
        attachedFiles = [];
        photoPreview.innerHTML = '';
        container.querySelectorAll('.priority-btn').forEach(btn => {
          btn.style.background = 'transparent';
          btn.style.color = 'var(--text)';
        });
        reporterNameInput.value = currentUser.name;
      }
    } catch (error) {
      alert('緊急報告の送信に失敗しました');
    }
  });

  // 報告完了ボタン
  container.querySelector('#btn-complete').addEventListener('click', () => {
    window.showScreen("scr-1778907133295");
  });

  // ボタンホバー効果
  container.addEventListener('mouseover', (e) => {
    if (e.target.id === 'btn-submit') {
      e.target.style.background = 'var(--primary-hover)';
    } else if (e.target.id === 'btn-draft') {
      e.target.style.background = 'rgba(255,255,255,0.05)';
    } else if (e.target.id === 'btn-complete') {
      e.target.style.background = '#059669';
    }
  });

  container.addEventListener('mouseout', (e) => {
    if (e.target.id === 'btn-submit') {
      e.target.style.background = 'var(--primary)';
    } else if (e.target.id === 'btn-draft') {
      e.target.style.background = 'transparent';
    } else if (e.target.id === 'btn-complete') {
      e.target.style.background = '#10b981';
    }
  });
}

function(container, apiUrl, tables) {
  let workRecords = [];
  let workItems = [];
  let selectedRecord = null;
  let originalData = null;

  // エラー・警告表示関数
  function showError(message) {
    const errorDiv = container.querySelector('#error-display');
    errorDiv.textContent = message;
    errorDiv.style.display = 'block';
    container.querySelector('#warning-display').style.display = 'none';
  }

  function showWarning(message) {
    const warningDiv = container.querySelector('#warning-display');
    warningDiv.textContent = message;
    warningDiv.style.display = 'block';
    container.querySelector('#error-display').style.display = 'none';
  }

  function hideMessages() {
    container.querySelector('#error-display').style.display = 'none';
    container.querySelector('#warning-display').style.display = 'none';
  }

  // 時刻計算関数
  function calculateWorkTime() {
    const startTime = container.querySelector('#input-start-time').value;
    const endTime = container.querySelector('#input-end-time').value;
    const breakTime = parseInt(container.querySelector('#input-break-time').value) || 0;

    if (!startTime || !endTime) {
      container.querySelector('#input-total-time').value = '';
      container.querySelector('#input-net-time').value = '';
      return;
    }

    const start = new Date(`2000-01-01 ${startTime}`);
    let end = new Date(`2000-01-01 ${endTime}`);

    // 24時間跨ぎの場合
    if (end <= start) {
      end.setDate(end.getDate() + 1);
    }

    const totalMinutes = (end - start) / (1000 * 60);
    const netMinutes = totalMinutes - breakTime;

    const totalHours = Math.floor(totalMinutes / 60);
    const totalMins = totalMinutes % 60;
    container.querySelector('#input-total-time').value = `${totalHours}時間${totalMins}分`;

    if (netMinutes >= 0) {
      const netHours = Math.floor(netMinutes / 60);
      const netMins = netMinutes % 60;
      container.querySelector('#input-net-time').value = `${netHours}時間${netMins}分`;
    } else {
      container.querySelector('#input-net-time').value = '';
    }
  }

  // バリデーション関数
  function validateForm() {
    hideMessages();

    const recordId = container.querySelector('#select-work-record').value;
    if (!recordId) {
      showError('修正対象の作業記録を選択してください');
      return false;
    }

    const startTime = container.querySelector('#input-start-time').value;
    const endTime = container.querySelector('#input-end-time').value;
    const breakTime = parseInt(container.querySelector('#input-break-time').value) || 0;
    const correctionReason = container.querySelector('#input-correction-reason').value.trim();

    if (!startTime || !endTime) {
      showError('作業開始時刻と終了時刻を入力してください');
      return false;
    }

    const start = new Date(`2000-01-01 ${startTime}`);
    let end = new Date(`2000-01-01 ${endTime}`);

    if (end <= start) {
      end.setDate(end.getDate() + 1);
    }

    if (start.getTime() === end.getTime()) {
      showError('作業時間が0分です。開始時刻と終了時刻を確認してください。');
      return false;
    }

    const totalMinutes = (end - start) / (1000 * 60);

    if (breakTime > totalMinutes) {
      showError('中断時間が作業時間を超過しています');
      return false;
    }

    if (!correctionReason) {
      showError('修正理由を入力してください');
      return false;
    }

    // 異常値チェック
    if (totalMinutes > 16 * 60) { // 16時間超過
      showWarning('作業時間が異常です。16時間を超える作業時間が入力されています。');
    }

    return true;
  }

  // 作業記録選択ドロップダウンの更新
  function updateWorkRecordSelect() {
    const select = container.querySelector('#select-work-record');
    select.innerHTML = '<option value="">選択してください</option>';

    workRecords.forEach(record => {
      const option = document.createElement('option');
      option.value = record.作業記録ID;
      const workDate = new Date(record.作業日).toLocaleDateString('ja-JP');
      option.textContent = `${workDate} - ${record.プロジェクト名} (${record.作業種別})`;
      select.appendChild(option);
    });
  }

  // 作業項目選択ドロップダウンの更新
  function updateWorkItemSelect() {
    const select = container.querySelector('#select-work-item');
    select.innerHTML = '<option value="">選択してください</option>';

    workItems.forEach(item => {
      const option = document.createElement('option');
      option.value = item.作業項目ID;
      option.textContent = `${item.作業項目コード} - ${item.作業項目名}`;
      select.appendChild(option);
    });
  }

  // フォームクリア
  function clearForm() {
    container.querySelector('#input-work-date').value = '';
    container.querySelector('#input-start-time').value = '';
    container.querySelector('#input-end-time').value = '';
    container.querySelector('#input-break-time').value = '';
    container.querySelector('#input-total-time').value = '';
    container.querySelector('#input-net-time').value = '';
    container.querySelector('#select-work-item').value = '';
    container.querySelector('#textarea-work-detail').value = '';
    container.querySelector('#input-correction-reason').value = '';
    selectedRecord = null;
    originalData = null;
    hideMessages();
  }

  // 作業記録選択時の処理
  container.querySelector('#select-work-record').addEventListener('change', function() {
    const recordId = this.value;
    if (!recordId) {
      clearForm();
      return;
    }

    selectedRecord = workRecords.find(r => r.作業記録ID === recordId);
    if (!selectedRecord) return;

    // 元データを保存
    originalData = { ...selectedRecord };

    // フォームに値を設定
    const workDate = new Date(selectedRecord.作業日).toLocaleDateString('ja-JP');
    container.querySelector('#input-work-date').value = workDate;

    const startTime = new Date(selectedRecord.作業開始時刻);
    const endTime = selectedRecord.作業終了時刻? new Date(selectedRecord.作業終了時刻) : null;

    container.querySelector('#input-start-time').value = startTime.toTimeString().slice(0, 5);
    if (endTime) {
      container.querySelector('#input-end-time').value = endTime.toTimeString().slice(0, 5);
    }

    container.querySelector('#textarea-work-detail').value = selectedRecord.作業内容 || '';

    // 中断時間を計算（中断記録から）
    window.aivicApi.list(2).then(breakRecords => {
      const relatedBreaks = breakRecords.filter(b => b.作業記録ID === recordId);
      const totalBreakTime = relatedBreaks.reduce((sum, b) => sum + (b.中断時間 || 0), 0);
      container.querySelector('#input-break-time').value = totalBreakTime;
      calculateWorkTime();
    });

    calculateWorkTime();
    hideMessages();
  });

  // 時刻・中断時間変更時の計算
  container.querySelector('#input-start-time').addEventListener('change', calculateWorkTime);
  container.querySelector('#input-end-time').addEventListener('change', calculateWorkTime);
  container.querySelector('#input-break-time').addEventListener('input', calculateWorkTime);

  // 保存ボタン
  container.querySelector('#btn-save').addEventListener('click', async function() {
    if (!validateForm()) return;

    const recordId = container.querySelector('#select-work-record').value;
    const startTime = container.querySelector('#input-start-time').value;
    const endTime = container.querySelector('#input-end-time').value;
    const breakTime = parseInt(container.querySelector('#input-break-time').value) || 0;
    const workItemId = container.querySelector('#select-work-item').value;
    const workDetail = container.querySelector('#textarea-work-detail').value;
    const correctionReason = container.querySelector('#input-correction-reason').value;

    // 作業時間計算
    const start = new Date(`2000-01-01 ${startTime}`);
    let end = new Date(`2000-01-01 ${endTime}`);
    if (end <= start) {
      end.setDate(end.getDate() + 1);
    }
    const totalMinutes = (end - start) / (1000 * 60);

    try {
      // 作業記録を更新
      const workDate = new Date(selectedRecord.作業日);
      const startDateTime = new Date(workDate);
      const [startHour, startMin] = startTime.split(':');
      startDateTime.setHours(parseInt(startHour), parseInt(startMin), 0, 0);

      const endDateTime = new Date(workDate);
      const [endHour, endMin] = endTime.split(':');
      endDateTime.setHours(parseInt(endHour), parseInt(endMin), 0, 0);
      if (endDateTime <= startDateTime) {
        endDateTime.setDate(endDateTime.getDate() + 1);
      }

      const updateData = {
        作業開始時刻: startDateTime.toISOString(),
        作業終了時刻: endDateTime.toISOString(),
        作業時間: totalMinutes,
        作業内容: workDetail,
        更新日時: new Date().toISOString()
      };

      const updated = await window.aivicApi.update(1, recordId, updateData);
      if (updated) {
        // 異常値検出ログを記録
        if (totalMinutes > 16 * 60) {
          await window.aivicApi.save(4, {
            異常値検出ログID: crypto.randomUUID(),
            検出対象テーブル: '作業記録',
            検出対象レコードID: recordId,
            ユーザーID: selectedRecord.作業員ID,
            異常値種別: '長時間作業',
            検出項目: '作業時間',
            検出値: `${totalMinutes}分`,
            閾値: '960分',
            重要度: '高',
            確認状況: '未確認',
            通知送信フラグ: false,
            検出日時: new Date().toISOString(),
            作成日時: new Date().toISOString(),
            更新日時: new Date().toISOString()
          });
        }

        alert('工数修正が完了しました');
        window.showScreen("scr-1778907367889");
      }
    } catch (error) {
      showError('保存に失敗しました');
    }
  });

  // 元データ参照ボタン
  container.querySelector('#btn-view-original').addEventListener('click', function() {
    if (!originalData) {
      showError('修正対象の作業記録を選択してください');
      return;
    }

    const modal = container.querySelector('#original-data-modal');
    const content = container.querySelector('#original-data-content');

    const startTime = new Date(originalData.作業開始時刻).toLocaleString('ja-JP');
    const endTime = originalData.作業終了時刻 ? new Date(originalData.作業終了時刻).toLocaleString('ja-JP') : '未設定';
    const workDate = new Date(originalData.作業日).toLocaleDateString('ja-JP');

    content.innerHTML = `
      <div style="margin-bottom: 8px;"><strong>作業日:</strong> ${workDate}</div>
      <div style="margin-bottom: 8px;"><strong>開始時刻:</strong> ${startTime}</div>
      <div style="margin-bottom: 8px;"><strong>終了時刻:</strong> ${endTime}</div>
      <div style="margin-bottom: 8px;"><strong>作業時間:</strong> ${originalData.作業時間 || 0}分</div>
      <div style="margin-bottom: 8px;"><strong>プロジェクト名:</strong> ${originalData.プロジェクト名 || ''}</div>
      <div style="margin-bottom: 8px;"><strong>作業種別:</strong> ${originalData.作業種別 || ''}</div>
      <div style="margin-bottom: 8px;"><strong>作業内容:</strong> ${originalData.作業内容 || ''}</div>
    `;

    modal.style.display = 'block';
  });

  // モーダル閉じるボタン
  container.querySelector('#btn-close-modal').addEventListener('click', function() {
    container.querySelector('#original-data-modal').style.display = 'none';
  });

  // キャンセルボタン
  container.querySelector('#btn-cancel').addEventListener('click', function() {
    window.showScreen("scr-1778907367889");
  });

  // 初期データ読み込み
  async function loadInitialData() {
    try {
      workRecords = await window.aivicApi.list(1) || [];
      workItems = await window.aivicApi.list(3) || [];

      updateWorkRecordSelect();
      updateWorkItemSelect();
    } catch (error) {
      console.error('データ読み込みエラー:', error);
    }
  }

  loadInitialData();
}

function(container, apiUrl, tables) {
  let currentResults = [];

  // DOM要素の取得
  const startDateInput = container.querySelector('#start-date');
  const endDateInput = container.querySelector('#end-date');
  const outputFormatSelect = container.querySelector('#output-format');
  const workerSelect = container.querySelector('#worker-select');
  const workItemSelect = container.querySelector('#work-item-select');
  const workLocationInput = container.querySelector('#work-location');
  const includeAnomaliesCheckbox = container.querySelector('#include-anomalies');
  const includeInterruptionsCheckbox = container.querySelector('#include-interruptions');
  const errorMessage = container.querySelector('#error-message');
  const conditionPreview = container.querySelector('#condition-preview');
  const dataCount = container.querySelector('#data-count');
  const resultTbody = container.querySelector('#result-tbody');
  const saveConditionModal = container.querySelector('#save-condition-modal');
  const conditionNameInput = container.querySelector('#condition-name');

  // 初期データの設定
  function initializeSelects() {
    // 作業員選択の初期化
    const users = tables[0]?.records || [];
    workerSelect.innerHTML = '<option value="">全作業員</option>';
    users.forEach(user => {
      const option = document.createElement('option');
      option.value = user.ユーザーID;
      option.textContent = user.氏名;
      workerSelect.appendChild(option);
    });

    // 作業項目選択の初期化
    const workItems = tables[3]?.records || [];
    workItemSelect.innerHTML = '<option value="">全作業項目</option>';
    workItems.forEach(item => {
      const option = document.createElement('option');
      option.value = item.作業項目ID;
      option.textContent = item.作業項目名;
      workItemSelect.appendChild(option);
    });
  }

  // エラーメッセージ表示
  function showError(message) {
    errorMessage.textContent = message;
    errorMessage.style.display = 'block';
  }

  function hideError() {
    errorMessage.style.display = 'none';
  }

  // 条件プレビュー更新
  function updatePreview() {
    const conditions = [];

    if (startDateInput.value && endDateInput.value) {
      conditions.push(`期間: ${startDateInput.value} ～ ${endDateInput.value}`);
    }

    const selectedWorkers = Array.from(workerSelect.selectedOptions).map(opt => opt.textContent);
    if (selectedWorkers.length > 0 && !selectedWorkers.includes('全作業員')) {
      conditions.push(`作業員: ${selectedWorkers.join(', ')}`);
    }

    const selectedItems = Array.from(workItemSelect.selectedOptions).map(opt => opt.textContent);
    if (selectedItems.length > 0 && !selectedItems.includes('全作業項目')) {
      conditions.push(`作業項目: ${selectedItems.join(', ')}`);
    }

    if (workLocationInput.value) {
      conditions.push(`作業場所: ${workLocationInput.value}`);
    }

    const options = [];
    if (includeAnomaliesCheckbox.checked) options.push('異常値含む');
    if (includeInterruptionsCheckbox.checked) options.push('中断記録含む');
    if (options.length > 0) {
      conditions.push(`オプション: ${options.join(', ')}`);
    }

    conditionPreview.textContent = conditions.length > 0 ? conditions.join(' / ') : '条件を設定してください';
  }

  // バリデーション
  function validateConditions() {
    hideError();

    if (!startDateInput.value || !endDateInput.value) {
      showError('抽出期間を指定してください');
      return false;
    }

    if (new Date(startDateInput.value) > new Date(endDateInput.value)) {
      showError('開始日は終了日より前の日付を入力してください');
      return false;
    }

    if (!outputFormatSelect.value) {
      showError('出力形式を選択してください');
      return false;
    }

    return true;
  }

  // 結果テーブル描画
  function renderResults(results) {
    if (results.length === 0) {
      resultTbody.innerHTML = '<tr><td colspan="7" style="text-align: center; color: var(--text-muted); padding: 20px;">該当するデータが見つかりませんでした</td></tr>';
      dataCount.textContent = '件数: 0件';
      return;
    }

    resultTbody.innerHTML = results.map(record => {
      const user = tables[0]?.records?.find(u => u.ユーザーID === record.作業員ID);
      const workDate = new Date(record.作業日).toLocaleDateString('ja-JP');
      const workTime = record.作業時間 ? `${Math.floor(record.作業時間 / 60)}時間${record.作業時間 % 60}分` : '-';

      return `
        <tr>
          <td>${workDate}</td>
          <td>${user?.氏名 || '-'}</td>
          <td>${workTime}</td>
          <td>${record.プロジェクト名 || '-'}</td>
          <td>${record.作業場所 || '-'}</td>
          <td>${record.作業種別 || '-'}</td>
          <td>${record.進捗状況 || '-'}</td>
        </tr>
      `;
    }).join('');

    dataCount.textContent = `件数: ${results.length}件`;
  }

  // データ抽出実行
  async function executeExtraction() {
    if (!validateConditions()) return;

    try {
      const workRecords = await window.aivicApi.list(1);
      if (!workRecords) {
        showError('データの取得に失敗しました');
        return;
      }

      let filteredResults = workRecords.filter(record => {
        const recordDate = new Date(record.作業日);
        const startDate = new Date(startDateInput.value);
        const endDate = new Date(endDateInput.value);

        if (recordDate < startDate || recordDate > endDate) return false;

        // 作業員フィルタ
        const selectedWorkers = Array.from(workerSelect.selectedOptions).map(opt => opt.value).filter(v => v);
        if (selectedWorkers.length > 0 && !selectedWorkers.includes(record.作業員ID)) return false;

        // 作業場所フィルタ
        if (workLocationInput.value && !record.作業場所?.includes(workLocationInput.value)) return false;

        return true;
      });

      // 異常値除外処理
      if (!includeAnomaliesCheckbox.checked) {
        const anomalyLogs = await window.aivicApi.list(4);
        if (anomalyLogs) {
          const anomalyRecordIds = anomalyLogs.map(log => log.検出対象レコードID);
          filteredResults = filteredResults.filter(record => !anomalyRecordIds.includes(record.作業記録ID));
        }
      }

      // 中断記録処理
      if (includeInterruptionsCheckbox.checked) {
        const interruptionRecords = await window.aivicApi.list(2);
        if (interruptionRecords) {
          // 中断記録を結果に含める処理（実装は簡略化）
        }
      }

      currentResults = filteredResults;
      renderResults(currentResults);

      // ファイルダウンロード処理
      if (outputFormatSelect.value === 'csv') {
        downloadCSV(currentResults);
      } else if (outputFormatSelect.value === 'excel') {
        downloadExcel(currentResults);
      }

    } catch (error) {
      showError('データ抽出中にエラーが発生しました');
      console.error('Extraction error:', error);
    }
  }

  // CSV ダウンロード
  function downloadCSV(data) {
    const headers = ['作業日', '作業員', '作業時間', 'プロジェクト名', '作業場所', '作業種別', '進捗状況'];
    const csvContent = '\uFEFF' + [
      headers.join(','),
      ...data.map(record => {
        const user = tables[0]?.records?.find(u => u.ユーザーID === record.作業員ID);
        const workDate = new Date(record.作業日).toLocaleDateString('ja-JP');
        const workTime = record.作業時間 ? `${Math.floor(record.作業時間 / 60)}時間${record.作業時間 % 60}分` : '';

        return [
          workDate,
          user?.氏名 || '',
          workTime,
          record.プロジェクト名 || '',
          record.作業場所 || '',
          record.作業種別 || '',
          record.進捗状況 || ''
        ].map(field => `"${field}"`).join(',');
      })
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `工数記録_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  }

  // Excel ダウンロード（CSV形式で代用）
  function downloadExcel(data) {
    downloadCSV(data); // 簡略化のためCSVと同じ処理
  }

  // 条件クリア
  function clearConditions() {
    startDateInput.value = '';
    endDateInput.value = '';
    outputFormatSelect.value = '';
    workerSelect.selectedIndex = 0;
    workItemSelect.selectedIndex = 0;
    workLocationInput.value = '';
    includeAnomaliesCheckbox.checked = false;
    includeInterruptionsCheckbox.checked = false;
    hideError();
    updatePreview();

    resultTbody.innerHTML = '<tr><td colspan="7" style="text-align: center; color: var(--text-muted); padding: 20px;">抽出条件を設定して実行してください</td></tr>';
    dataCount.textContent = '件数: 0件';
  }

  // 条件保存
  function saveCondition() {
    const conditionName = conditionNameInput.value.trim();
    if (!conditionName) {
      alert('条件名を入力してください');
      return;
    }

    const condition = {
      name: conditionName,
      startDate: startDateInput.value,
      endDate: endDateInput.value,
      outputFormat: outputFormatSelect.value,
      workers: Array.from(workerSelect.selectedOptions).map(opt => opt.value),
      workItems: Array.from(workItemSelect.selectedOptions).map(opt => opt.value),
      workLocation: workLocationInput.value,
      includeAnomalies: includeAnomaliesCheckbox.checked,
      includeInterruptions: includeInterruptionsCheckbox.checked
    };

    // ローカルストレージに保存（実装簡略化）
    const savedConditions = JSON.parse(localStorage.getItem('extractionConditions') || '[]');
    savedConditions.push(condition);
    localStorage.setItem('extractionConditions', JSON.stringify(savedConditions));

    alert('条件が保存されました');
    saveConditionModal.style.display = 'none';
    conditionNameInput.value = '';
  }

  // イベントリスナー設定
  startDateInput.addEventListener('change', updatePreview);
  endDateInput.addEventListener('change', updatePreview);
  workerSelect.addEventListener('change', updatePreview);
  workItemSelect.addEventListener('change', updatePreview);
  workLocationInput.addEventListener('input', updatePreview);
  includeAnomaliesCheckbox.addEventListener('change', updatePreview);
  includeInterruptionsCheckbox.addEventListener('change', updatePreview);

  container.querySelector('#btn-extract').addEventListener('click', executeExtraction);
  container.querySelector('#btn-clear').addEventListener('click', clearConditions);
  container.querySelector('#btn-save-condition').addEventListener('click', () => {
    saveConditionModal.style.display = 'block';
  });
  container.querySelector('#btn-back').addEventListener('click', () => {
    window.showScreen("scr-1778907145716");
  });

  // モーダル関連
  container.querySelector('#btn-cancel-save').addEventListener('click', () => {
    saveConditionModal.style.display = 'none';
    conditionNameInput.value = '';
  });
  container.querySelector('#btn-confirm-save').addEventListener('click', saveCondition);

  // 初期化
  initializeSelects();
  updatePreview();
}

function(container, apiUrl, tables) {
  const tbody = container.querySelector("#records-tbody");
  const emptyMessage = container.querySelector("#empty-message");
  const detailModal = container.querySelector("#detail-modal");
  const detailContent = container.querySelector("#detail-content");

  // ユーザー情報をマップ化
  const userMap = {};
  if (tables[0]) {
    tables[0].records.forEach(user => {
      userMap[user.ユーザーID] = user.氏名;
    });
  }

  // 中断記録をマップ化
  const breakMap = {};
  if (tables[2]) {
    tables[2].records.forEach(breakRecord => {
      if (!breakMap[breakRecord.作業記録ID]) {
        breakMap[breakRecord.作業記録ID] = 0;
      }
      breakMap[breakRecord.作業記録ID] += breakRecord.中断時間 || 0;
    });
  }

  // 異常値検出ログをマップ化
  const anomalyMap = {};
  if (tables[4]) {
    tables[4].records.forEach(anomaly => {
      if (anomaly.検出対象テーブル === '作業記録') {
        anomalyMap[anomaly.検出対象レコードID] = anomaly;
      }
    });
  }

  function formatTime(timeStr) {
    if (!timeStr) return '';
    const date = new Date(timeStr);
    return date.toLocaleTimeString('ja-JP', { hour: '2-digit', minute: '2-digit' });
  }

  function formatDate(dateStr) {
    if (!dateStr) return '';
    const date = new Date(dateStr);
    return date.toLocaleDateString('ja-JP');
  }

  function calculateWorkTime(startTime, endTime) {
    if (!startTime || !endTime) return 0;
    const start = new Date(startTime);
    const end = new Date(endTime);
    return Math.floor((end - start) / (1000 * 60)); // 分単位
  }

  function formatWorkTime(minutes) {
    if (!minutes) return '0分';
    const hours = Math.floor(minutes / 60);
    const mins = minutes % 60;
    if (hours > 0) {
      return mins > 0 ? `${hours}時間${mins}分` : `${hours}時間`;
    }
    return `${mins}分`;
  }

  function getStatusBadge(status) {
    const colors = {
      '未承認': 'background: rgba(255, 193, 7, 0.2); color: #856404; border: 1px solid rgba(255, 193, 7, 0.3);',
      '承認済み': 'background: rgba(40, 167, 69, 0.2); color: #155724; border: 1px solid rgba(40, 167, 69, 0.3);',
      '差し戻し': 'background: rgba(220, 53, 69, 0.2); color: #721c24; border: 1px solid rgba(220, 53, 69, 0.3);'
    };
    return `<span style="padding: 2px 6px; border-radius: 4px; font-size: 11px; font-weight: 500; ${colors[status] || colors['未承認']}">${status}</span>`;
  }

  function renderRows(rows) {
    if (!rows || rows.length === 0) {
      tbody.innerHTML = '';
      emptyMessage.classList.remove('hidden');
      return;
    }

    emptyMessage.classList.add('hidden');

    tbody.innerHTML = rows.map(record => {
      const workTime = calculateWorkTime(record.作業開始時刻, record.作業終了時刻);
      const breakTime = breakMap[record.作業記録ID] || 0;
      const hasAnomaly = anomalyMap[record.作業記録ID];
      const userName = userMap[record.作業員ID] || '不明';
      const isApproved = record.承認状態 === '承認済み';

      // 異常値チェック
      let anomalyIcon = '';
      if (hasAnomaly || workTime > 1440 || (record.作業終了時刻&& new Date(record.作業終了時刻) < new Date(record.作業開始時刻)) || breakTime > workTime) {
        anomalyIcon = '<span style="color: #dc3545; margin-left: 4px;" title="異常値を検出">⚠️</span>';
      }

      return `
        <tr data-id="${record.作業記録ID}" style="border-bottom: 1px solid rgba(255,255,255,0.05);">
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${formatDate(record.作業日)}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${userName}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${formatTime(record.作業開始時刻)}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${formatTime(record.作業終了時刻)}${anomalyIcon}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${formatWorkTime(workTime)}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${formatWorkTime(breakTime)}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text); max-width: 200px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;">${record.作業内容 || ''}</td>
          <td style="padding: 6px 10px; font-size: 13px;">${getStatusBadge(record.承認状態)}</td>
          <td style="padding: 6px 10px; font-size: 13px;">
            <button class="action-btn secondary detail-btn" data-id="${record.作業記録ID}" style="background: transparent; color: var(--text); border: 1px solid rgba(255,255,255,0.18); padding: 4px 8px; border-radius: 4px; font-size: 11px; cursor: pointer; margin-right: 4px;">詳細</button>
            <button class="action-btn edit-btn" data-id="${record.作業記録ID}" ${isApproved ? 'disabled' : ''} style="background: var(--primary); color: #fff; border: none; padding: 4px 8px; border-radius: 4px; font-size: 11px; cursor: pointer; margin-right: 4px; ${isApproved ? 'opacity: 0.5; cursor: not-allowed;' : ''}">修正</button>
            <button class="action-btn secondary delete-btn" data-id="${record.作業記録ID}" ${isApproved ? 'disabled' : ''} style="background: transparent; color: var(--text); border: 1px solid rgba(255,255,255,0.18); padding: 4px 8px; border-radius: 4px; font-size: 11px; cursor: pointer; margin-right: 4px; ${isApproved ? 'opacity: 0.5; cursor: not-allowed;' : ''}">削除</button>
            <button class="action-btn approve-btn" data-id="${record.作業記録ID}" ${isApproved ? 'disabled' : ''} style="background: #28a745; color: #fff; border: none; padding: 4px 8px; border-radius: 4px; font-size: 11px; cursor: pointer; ${isApproved ? 'opacity: 0.5; cursor: not-allowed;' : ''}">承認</button>
          </td>
        </tr>
      `;
    }).join('');
  }

  function showDetail(recordId) {
    const record = tables[1].records.find(r => r.作業記録ID === recordId);
    if (!record) return;

    const workTime = calculateWorkTime(record.作業開始時刻, record.作業終了時刻);
    const breakTime = breakMap[record.作業記録ID] || 0;
    const userName = userMap[record.作業員ID] || '不明';
    const anomaly = anomalyMap[record.作業記録ID];

    let anomalyInfo = '';
    if (anomaly) {
      anomalyInfo = `
        <div style="background: rgba(220, 53, 69, 0.1); border: 1px solid rgba(220, 53, 69, 0.3); border-radius: 6px; padding: 12px; margin-bottom: 16px;">
          <h4 style="font-size: 13px; font-weight: 600; color: #dc3545; margin: 0 0 8px 0;">異常値検出</h4>
          <p style="font-size: 12px; color: var(--text); margin: 0;"><strong>種別:</strong> ${anomaly.異常値種別}</p>
          <p style="font-size: 12px; color: var(--text); margin: 4px 0 0 0;"><strong>検出項目:</strong> ${anomaly.検出項目}</p>
          <p style="font-size: 12px; color: var(--text); margin: 4px 0 0 0;"><strong>検出値:</strong> ${anomaly.検出値}</p>
        </div>
      `;
    }

    detailContent.innerHTML = `
      ${anomalyInfo}
      <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 16px;">
        <div>
          <h4 style="font-size: 13px; font-weight: 600; color: var(--text); margin: 0 0 8px 0;">基本情報</h4>
          <p style="font-size: 12px; color: var(--text); margin: 4px 0;"><strong>作業日:</strong> ${formatDate(record.作業日)}</p>
          <p style="font-size: 12px; color: var(--text); margin: 4px 0;"><strong>作業者:</strong> ${userName}</p>
          <p style="font-size: 12px; color: var(--text); margin: 4px 0;"><strong>プロジェクト:</strong> ${record.プロジェクト名 || ''}</p>
          <p style="font-size: 12px; color: var(--text); margin: 4px 0;"><strong>作業場所:</strong> ${record.作業場所 || ''}</p>
          <p style="font-size: 12px; color: var(--text); margin: 4px 0;"><strong>作業種別:</strong> ${record.作業種別 || ''}</p>
        </div>
        <div>
          <h4 style="font-size: 13px; font-weight: 600; color: var(--text); margin: 0 0 8px 0;">時間情報</h4>
          <p style="font-size: 12px; color: var(--text); margin: 4px 0;"><strong>開始時刻:</strong> ${formatTime(record.作業開始時刻)}</p>
          <p style="font-size: 12px; color: var(--text); margin: 4px 0;"><strong>終了時刻:</strong> ${formatTime(record.作業終了時刻)}</p>
          <p style="font-size: 12px; color: var(--text); margin: 4px 0;"><strong>作業時間:</strong> ${formatWorkTime(workTime)}</p>
          <p style="font-size: 12px; color: var(--text); margin: 4px 0;"><strong>中断時間:</strong> ${formatWorkTime(breakTime)}</p>
          <p style="font-size: 12px; color: var(--text); margin: 4px 0;"><strong>実働時間:</strong> ${formatWorkTime(workTime - breakTime)}</p>
        </div>
      </div>
      <div style="margin-top: 16px;">
        <h4 style="font-size: 13px; font-weight: 600; color: var(--text); margin: 0 0 8px 0;">作業内容</h4>
        <p style="font-size: 12px; color: var(--text); margin: 0; line-height: 1.5; background: rgba(0,0,0,0.1); padding: 8px; border-radius: 4px;">${record.作業内容 || '記載なし'}</p>
      </div>
      ${record.備考 ? `
        <div style="margin-top: 16px;">
          <h4 style="font-size: 13px; font-weight: 600; color: var(--text); margin: 0 0 8px 0;">備考</h4>
          <p style="font-size: 12px; color: var(--text); margin: 0; line-height: 1.5; background: rgba(0,0,0,0.1); padding: 8px; border-radius: 4px;">${record.備考}</p>
        </div>
      ` : ''}
    `;

    detailModal.classList.remove('hidden');
  }

  function exportCSV() {
    window.aivicApi.list(1).then(rows => {
      if (!rows || rows.length === 0) {
        alert('エクスポートするデータがありません');
        return;
      }

      const headers = ['作業日', '作業者', '開始時刻', '終了時刻', '作業時間', '中断時間', '実働時間', 'プロジェクト名', '作業場所', '作業種別', '作業内容', '承認状態', '備考'];
      const csvData = [headers.join(',')];

      rows.forEach(record => {
        const workTime = calculateWorkTime(record.作業開始時刻, record.作業終了時刻);
        const breakTime = breakMap[record.作業記録ID] || 0;
        const userName = userMap[record.作業員ID] || '不明';

        const row = [
          formatDate(record.作業日),
          userName,
          formatTime(record.作業開始時刻),
          formatTime(record.作業終了時刻),
          formatWorkTime(workTime),
          formatWorkTime(breakTime),
          formatWorkTime(workTime - breakTime),
          record.プロジェクト名 || '',
          record.作業場所 || '',
          record.作業種別 || '',
          `"${(record.作業内容 || '').replace(/"/g, '""')}"`,
          record.承認状態 || '',
          `"${(record.備考 || '').replace(/"/g, '""')}"`
        ];
        csvData.push(row.join(','));
      });

      const csv = '\uFEFF' + csvData.join('\n');
      const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
      const link = document.createElement('a');
      link.href = URL.createObjectURL(blob);
      link.download = `工数記録_${new Date().toISOString().split('T')[0]}.csv`;
      link.click();
    });
  }

  // 初期データ表示
  renderRows(tables[1]?.records || []);

  // 検索・絞り込み
  container.querySelector("#btn-search").addEventListener("click", () => {
    const dateFilter = container.querySelector("#date-filter").value;
    const startDate = container.querySelector("#start-date").value;
    const endDate = container.querySelector("#end-date").value;

    // 日付バリデーション
    if (startDate && endDate && new Date(startDate) > new Date(endDate)) {
      alert('開始日は終了日より前の日付を指定してください');
      return;
    }

    window.aivicApi.list(1).then(rows => {
      if (!rows) return;

      let filteredRows = rows;

      if (dateFilter) {
        filteredRows = filteredRows.filter(r => {
          const recordDate = new Date(r.作業日).toISOString().split('T')[0];
          return recordDate === dateFilter;
        });
      }

      if (startDate) {
        filteredRows = filteredRows.filter(r => {
          const recordDate = new Date(r.作業日).toISOString().split('T')[0];
          return recordDate >= startDate;
        });
      }

      if (endDate) {
        filteredRows = filteredRows.filter(r => {
          const recordDate = new Date(r.作業日).toISOString().split('T')[0];
          return recordDate <= endDate;
        });
      }

      renderRows(filteredRows);
    });
  });

  // CSVエクスポート
  container.querySelector("#btn-export").addEventListener("click", exportCSV);

  // モーダル閉じる
  container.querySelector("#close-modal").addEventListener("click", () => {
    detailModal.classList.add('hidden');
  });

  // 行レベル操作
  container.addEventListener("click", async (e) => {
    const detailBtn = e.target.closest(".detail-btn");
    const editBtn = e.target.closest(".edit-btn");
    const deleteBtn = e.target.closest(".delete-btn");
    const approveBtn = e.target.closest(".approve-btn");

    if (detailBtn) {
      showDetail(detailBtn.dataset.id);
    }

    if (editBtn && !editBtn.disabled) {
      window.showScreen("scr-1778907343735");
    }

    if (deleteBtn && !deleteBtn.disabled) {
      if (!confirm("この工数記録を削除しますか？")) return;

      const result = await window.aivicApi.delete(1, deleteBtn.dataset.id);
      if (result !== null) {
        const rows = await window.aivicApi.list(1);
        if (rows) renderRows(rows);
      }
    }

    if (approveBtn && !approveBtn.disabled) {
      if (!confirm("この工数記録を承認しますか？")) return;

      const result = await window.aivicApi.update(1, approveBtn.dataset.id, {
        承認状態: '承認済み',
        承認日時: new Date().toISOString(),
        承認者ID: 'current-user-id' // 実際の実装では現在のユーザーIDを使用
      });

      if (result !== null) {
        const rows = await window.aivicApi.list(1);
        if (rows) renderRows(rows);
      }
    }
  });

  // 今日の日付を初期値に設定
  const today = new Date().toISOString().split('T')[0];
  container.querySelector("#date-filter").value = today;
}

function(container, apiUrl, tables) {
  // テーブルインデックス
  const WORK_RECORDS_TABLE = 1; // 作業記録テーブル
  const WORK_ITEMS_TABLE = 3; // 作業項目マスタテーブル

  // DOM要素取得
  const form = container.querySelector('#work-record-form');
  const workDateInput = container.querySelector('#work-date');
  const workerNameInput = container.querySelector('#worker-name');
  const projectNameSelect = container.querySelector('#project-name');
  const workItemSelect = container.querySelector('#work-item');
  const workLocationSelect = container.querySelector('#work-location');
  const workTypeSelect = container.querySelector('#work-type');
  const startTimeInput = container.querySelector('#start-time');
  const endTimeInput = container.querySelector('#end-time');
  const breakTimeInput = container.querySelector('#break-time');
  const workDetailsTextarea = container.querySelector('#work-details');
  const calculatedHoursDiv = container.querySelector('#calculated-hours');
  const charCountSpan = container.querySelector('#char-count');
  const errorMessagesDiv = container.querySelector('#error-messages');
  const recordsTbody = container.querySelector('#records-tbody');

  // ボタン要素
  const cancelBtn = container.querySelector('#cancel-btn');
  const tempSaveBtn = container.querySelector('#temp-save-btn');
  const saveBtn = container.querySelector('#save-btn');
  const addBreakBtn = container.querySelector('#add-break-btn');
  const calculateBtn = container.querySelector('#calculate-btn');

  // 初期値設定
  workDateInput.value = new Date().toISOString().split('T')[0];

  // 作業項目マスタの読み込み
  async function loadWorkItems() {
    try {
      const workItems = await window.aivicApi.list(WORK_ITEMS_TABLE);
      if (workItems) {
        workItemSelect.innerHTML = '<option value="">選択してください</option>';
        workItems.forEach(item => {
          const option = document.createElement('option');
          option.value = item.作業項目名 || item.name || '';
          option.textContent = item.作業項目名 || item.name || '';
          workItemSelect.appendChild(option);
        });
      }
    } catch (error) {
      console.error('作業項目の読み込みに失敗しました:', error);
    }
  }

  // 最近の工数記録を表示
  function renderRecentRecords(records) {
    if (!records || records.length === 0) {
      recordsTbody.innerHTML = '<tr><td colspan="6" style="text-align: center; padding: 20px; color: var(--text-muted);">記録がありません</td></tr>';
      return;
    }

    recordsTbody.innerHTML = records.slice(0, 5).map(record => `
      <tr data-id="${record.id || ''}">
        <td style="padding: 6px 10px; font-size: 13px;">${record.作業日 || ''}</td>
        <td style="padding: 6px 10px; font-size: 13px;">${record.プロジェクト名 || ''}</td>
        <td style="padding: 6px 10px; font-size: 13px;">${(record.作業内容 || '').substring(0, 30)}${(record.作業内容 || '').length > 30 ? '...' : ''}</td>
        <td style="padding: 6px 10px; font-size: 13px;">${record.作業時間 ? (record.作業時間 / 60).toFixed(1) + 'h' : '-'}</td>
        <td style="padding: 6px 10px; font-size: 13px;">
          <span style="padding: 2px 6px; border-radius: 3px; font-size: 11px; background: ${getStatusColor(record.承認状態)};">
            ${record.承認状態 || '未承認'}
          </span>
        </td>
        <td style="padding: 6px 10px; font-size: 13px;">
          <button class="action-btn secondary edit-btn" data-id="${record.id || ''}" style="font-size: 11px; padding: 2px 6px;">編集</button>
          <button class="action-btn secondary delete-btn" data-id="${record.id || ''}" style="font-size: 11px; padding: 2px 6px; margin-left: 4px;">削除</button>
        </td>
      </tr>
    `).join('');
  }

  function getStatusColor(status) {
    switch (status) {
      case '承認済み': return 'rgba(34, 197, 94, 0.2)';
      case '差し戻し': return 'rgba(239, 68, 68, 0.2)';
      default: return 'rgba(156, 163, 175, 0.2)';
    }
  }

  // 工数計算
  function calculateWorkHours() {
    const startTime = startTimeInput.value;
    const endTime = endTimeInput.value;
    const breakMinutes = parseInt(breakTimeInput.value) || 0;

    if (!startTime || !endTime) {
      calculatedHoursDiv.textContent = '0.0h';
      return 0;
    }

    const start = new Date(`2000-01-01T${startTime}`);
    const end = new Date(`2000-01-01T${endTime}`);

    if (end <= start) {
      calculatedHoursDiv.textContent = '0.0h';
      return 0;
    }

    const totalMinutes = (end - start) / (1000 * 60);
    const workMinutes = Math.max(0, totalMinutes - breakMinutes);
    const workHours = workMinutes / 60;

    calculatedHoursDiv.textContent = workHours.toFixed(1) + 'h';
    return workMinutes;
  }

  // バリデーション
  function validateForm() {
    const errors = [];

    if (!workDateInput.value) {
      errors.push('作業日を入力してください');
    } else {
      const workDate = new Date(workDateInput.value);
      const today = new Date();
      today.setHours(23, 59, 59, 999);
      if (workDate > today) {
        errors.push('未来日付は選択できません');
      }
    }

    if (!workerNameInput.value.trim()) {
      errors.push('作業員名を入力してください');
    }

    if (!projectNameSelect.value) {
      errors.push('プロジェクト名を選択してください');
    }

    if (!workItemSelect.value) {
      errors.push('作業項目を選択してください');
    }

    if (!workLocationSelect.value) {
      errors.push('作業場所を選択してください');
    }

    if (!workTypeSelect.value) {
      errors.push('作業種別を選択してください');
    }

    if (!startTimeInput.value) {
      errors.push('開始時刻を入力してください');
    }

    if (!workDetailsTextarea.value.trim()) {
      errors.push('作業内容詳細を入力してください');
    }

    if (startTimeInput.value && endTimeInput.value) {
      const start = new Date(`2000-01-01T${startTimeInput.value}`);
      const end = new Date(`2000-01-01T${endTimeInput.value}`);

      if (end <= start) {
        errors.push('開始時刻が終了時刻より後になっています');
      }

      const totalMinutes = (end - start) / (1000 * 60);
      if (totalMinutes >= 24 * 60) {
        errors.push('24時間以上の作業時間は入力できません');
      }

      const breakMinutes = parseInt(breakTimeInput.value) || 0;
      if (breakMinutes >= totalMinutes) {
        errors.push('中断時間は作業時間を超過できません');
      }
    }

    return errors;
  }

  // エラー表示
  function showErrors(errors) {
    if (errors.length === 0) {
      errorMessagesDiv.innerHTML = '';
      return;
    }

    errorMessagesDiv.innerHTML = `
      <div style="background: rgba(239, 68, 68, 0.1); border: 1px solid rgba(239, 68, 68, 0.3); border-radius: 6px; padding: 8px;">
        ${errors.map(error => `<div style="color: #ef4444; font-size: 12px; margin-bottom: 2px;">${error}</div>`).join('')}
      </div>
    `;
  }

  // 成功メッセージ表示
  function showSuccess(message) {
    errorMessagesDiv.innerHTML = `
      <div style="background: rgba(34, 197, 94, 0.1); border: 1px solid rgba(34, 197, 94, 0.3); border-radius: 6px; padding: 8px;">
        <div style="color: #22c55e; font-size: 12px;">${message}</div>
      </div>
    `;
    setTimeout(() => {
      errorMessagesDiv.innerHTML = '';
    }, 3000);
  }

  // フォームクリア
  function clearForm() {
    form.reset();
    workDateInput.value = new Date().toISOString().split('T')[0];
    breakTimeInput.value = '0';
    calculatedHoursDiv.textContent = '0.0h';
    charCountSpan.textContent = '0';
    errorMessagesDiv.innerHTML = '';
  }

  // 保存処理
  async function saveRecord(isTemp = false) {
    const errors = validateForm();
    if (errors.length > 0) {
      showErrors(errors);
      return;
    }

    const workMinutes = calculateWorkHours();

    const recordData = {
      作業員ID: 'current-user-id', // 実際の実装では認証されたユーザーIDを使用
      作業日: workDateInput.value,
      作業開始時刻: `${workDateInput.value}T${startTimeInput.value}`,
      作業終了時刻: endTimeInput.value ? `${workDateInput.value}T${endTimeInput.value}` : null,
      作業時間: workMinutes,
      プロジェクト名: projectNameSelect.value,
      作業場所: workLocationSelect.value,
      作業種別: workTypeSelect.value,
      作業内容: workDetailsTextarea.value,
      進捗状況: isTemp ? '一時保存' : '完了',
      備考: `中断時間: ${breakTimeInput.value}分`,
      承認状態: '未承認',
      作成日時: new Date().toISOString(),
      更新日時: new Date().toISOString(),
      作成者ID: 'current-user-id'
    };

    try {
      const saved = await window.aivicApi.save(WORK_RECORDS_TABLE, recordData);
      if (saved) {
        showSuccess(isTemp ? '一時保存しました' : '工数記録を登録しました');
        if (!isTemp) {
          clearForm();
        }
        loadRecentRecords();
      }
    } catch (error) {
      showErrors(['保存に失敗しました。もう一度お試しください。']);
    }
  }

  // 最近の記録読み込み
  async function loadRecentRecords() {
    try {
      const records = await window.aivicApi.list(WORK_RECORDS_TABLE);
      if (records) {
        const sortedRecords = records.sort((a, b) => new Date(b.作成日時 || 0) - new Date(a.作成日時 || 0));
        renderRecentRecords(sortedRecords);
      }
    } catch (error) {
      console.error('記録の読み込みに失敗しました:', error);
    }
  }

  // イベントリスナー設定

  // 文字数カウント
  workDetailsTextarea.addEventListener('input', () => {
    charCountSpan.textContent = workDetailsTextarea.value.length;
  });

  // 時刻変更時の自動計算
  startTimeInput.addEventListener('change', calculateWorkHours);
  endTimeInput.addEventListener('change', calculateWorkHours);
  breakTimeInput.addEventListener('input', calculateWorkHours);

  // 計算ボタン
  calculateBtn.addEventListener('click', calculateWorkHours);

  // 中断記録追加ボタン
  addBreakBtn.addEventListener('click', () => {
    window.showScreen('scr-1778907238439'); // 中断記録入力画面
  });

  // キャンセルボタン
  cancelBtn.addEventListener('click', () => {
    if (confirm('入力内容をクリアしますか？')) {
      clearForm();
    }
  });

  // 一時保存ボタン
  tempSaveBtn.addEventListener('click', () => {
    saveRecord(true);
  });

  // 記録確定ボタン
  saveBtn.addEventListener('click', () => {
    if (confirm('工数記録を確定しますか？')) {
      saveRecord(false);
    }
  });

  // ボタンホバー効果
  [cancelBtn, tempSaveBtn, addBreakBtn, calculateBtn].forEach(btn => {
    btn.addEventListener('mouseenter', () => {
      btn.style.background = 'rgba(255,255,255,0.05)';
    });
    btn.addEventListener('mouseleave', () => {
      btn.style.background = 'transparent';
    });
  });

  saveBtn.addEventListener('mouseenter', () => {
    saveBtn.style.background = 'var(--primary-hover)';
  });
  saveBtn.addEventListener('mouseleave', () => {
    saveBtn.style.background = 'var(--primary)';
  });

  // 行レベル操作（編集・削除）
  container.addEventListener('click', async (e) => {
    const editBtn = e.target.closest('.edit-btn');
    const deleteBtn = e.target.closest('.delete-btn');

    if (editBtn) {
      const recordId = editBtn.dataset.id;
      if (recordId) {
        window.showScreen('scr-1778907343735'); // 工数修正画面
      }
    }

    if (deleteBtn) {
      const recordId = deleteBtn.dataset.id;
      if (recordId && confirm('この記録を削除しますか？')) {
        try {
          await window.aivicApi.delete(WORK_RECORDS_TABLE, recordId);
          showSuccess('記録を削除しました');
          loadRecentRecords();
        } catch (error) {
          showErrors(['削除に失敗しました']);
        }
      }
    }
  });

  // 初期データ読み込み
  loadWorkItems();

  // 初期記録表示（tables から取得）
  if (tables && tables[WORK_RECORDS_TABLE] && tables[WORK_RECORDS_TABLE].records) {
    renderRecentRecords(tables[WORK_RECORDS_TABLE].records);
  }

  // 最新データ読み込み
  loadRecentRecords();
}
